                    local _, cnt_r = sigma_prefixes(rule.r, sigma)
                    local delta = cnt_r - cnt_l
                    if delta > 0 and not contains(rule.l, start) then
                        -- sigma-creating rule that can fire more than
                        -- once: the count is unbounded
                        n_max = nil
                        break
                    end
                    if #rule.l == 1 and rule.l[1] == start then
                        n_max = math.max(n_max, cnt_r)
                    end
                end
                if n_max and start == sigma then
                    n_max = math.max(n_max, 1)
                end
            end
            if n_max then
            local K = n_max
            local nvars = #syms * (K + 1)
            local function idx(sym, k)
                return (sym_index[sym] - 1) * (K + 1) + k + 1
            end
            -- rule l -> r at segment offset s contributes the exact
            -- region-parikh equation; only feasible offsets are used
            local function rule_rows(rule, s)
                local pl, cnt_l = sigma_prefixes(rule.l, sigma)
                local pr, cnt_r = sigma_prefixes(rule.r, sigma)
                local row = {}
                for i = 1, #rule.l do
                    local id = idx(rule.l[i], s + pl[i])
                    row[id] = (row[id] or 0) + 1
                end
                for j = 1, #rule.r do
                    local id = idx(rule.r[j], s + pr[j])
                    row[id] = (row[id] or 0) - 1
                end
                return row, cnt_l, cnt_r
            end
            local rows, deltas = {}, {}
            for _, rule in ipairs(rules) do
                local cnt_l = select(2, sigma_prefixes(rule.l, sigma))
                local cnt_r = select(2, sigma_prefixes(rule.r, sigma))
                if contains(rule.l, start) then
                    -- start-variable-containing lhs: applicable only to
                    -- the lone start form (if at all); no suffix, no
                    -- offset
                    if #rule.l == 1 then
                        rows[#rows + 1] = rule_rows(rule, 0)
                    end
                    -- longer lhs is dead code: no constraint
                else
                    for s = 0, K - cnt_l do
                        rows[#rows + 1] = rule_rows(rule, s)
                    end
                    local delta = cnt_r - cnt_l
                    if delta ~= 0 and K >= cnt_l then
                        -- suffix segments shift by delta; the weight
                        -- must be constant under the shift for every
                        -- segment a suffix symbol can occupy
                        deltas[#deltas + 1] =
                            {delta = delta, cnt_l = cnt_l}
                    end
                end
            end
            for _, d in ipairs(deltas) do
                for _, t in ipairs(syms) do
                    for k = d.cnt_l, K do
                        local row = {}
                        row[idx(t, k)] = 1
                        row[idx(t, k + d.delta)] = -1
                        rows[#rows + 1] = row
                    end
                end
            end
            -- exact verification of one integer weight vector against
            -- the same bounded-offset model
            local function verify(weights)
                for _, rule in ipairs(rules) do
                    local pl, cnt_l = sigma_prefixes(rule.l, sigma)
                    local pr, cnt_r = sigma_prefixes(rule.r, sigma)
                    local delta = cnt_r - cnt_l
                    if contains(rule.l, start) then
                        if #rule.l == 1 then
                            local sl, sr = 0, 0
                            for i = 1, #rule.l do
                                sl = sl + weights[idx(rule.l[i],
                                                     pl[i])]
                            end
                            for j = 1, #rule.r do
                                sr = sr + weights[idx(rule.r[j],
                                                     pr[j])]
                            end
                            if sl ~= sr then
                                return false
                            end
                        end
                    elseif K >= cnt_l then
                        for s = 0, K - cnt_l do
                            local sl, sr = 0, 0
                            for i = 1, #rule.l do
                                sl = sl + weights[idx(rule.l[i],
                                                     s + pl[i])]
                            end
                            for j = 1, #rule.r do
                                sr = sr + weights[idx(rule.r[j],
                                                     s + pr[j])]
                            end
                            if sl ~= sr then
                                return false
                            end
                        end
                        if delta ~= 0 then
                            for _, t in ipairs(syms) do
                                for k = cnt_l, K do
                                    if weights[idx(t, k)]
                                        ~= weights[idx(t, k + delta)] then
                                        return false
                                    end
                                end
                            end
                        end
                    end
                end
                return true
            end
            for _, b in ipairs(null_space_basis(rows, nvars)) do
                -- rationalise: small integers only, exact verify below
                local ints, dens, lcm = {}, {}, 1
                local ok = true
                for j = 1, nvars do
                    local p, q = approx_rational(b[j], 64)
                    ints[j], dens[j] = p, q
                    lcm = lcm * q / gcd_int(lcm, q)
                    if lcm > 1000000 then
                        ok = false
                        break
                    end
                end
                if ok then
                    local weights, g = {}, 0
                    for j = 1, nvars do
                        weights[j] = ints[j] * (lcm / dens[j])
                        g = gcd_int(g, weights[j])
                    end
                    if g > 1 then
                        for j = 1, nvars do
                            weights[j] = weights[j] / g
                        end
                    end
                    if verify(weights) then
                        local w = {}
                        for sym, si in pairs(sym_index) do
                            local arr = {}
                            for k = 0, K do
                                arr[k] = weights[idx(sym, k)]
                            end
                            w[sym] = arr
                        end
                        invariants[#invariants + 1] = {
                            sigma = sigma, k = K, w = w,
                            value = w[start][0],
                        }
                        if #invariants >= max_invariants then
                            done = true
                            break
                        end
                    end
                end
            end
            end
            if done then
                break
            end
        end
        return invariants
    end

    -- weighted value of a form under one invariant; nil when the form
    -- exceeds the invariant's proven segment bound (unreachable per
    -- bound, the weighting itself is not defined there)
    local function invariant_value(inv, form)
        local total, segs = 0, 0
        for i = 1, form:len() do
            local c = form:get_char(i)
            local w = inv.w[c]
            if w then
                if segs > inv.k then
                    return nil
                end
                total = total + w[segs]
            end
            if c == inv.sigma then
                segs = segs + 1
            end
        end
        if segs > inv.k then
            return nil
        end
        return total
    end

    -- invariants are per grammar object and cheap to reuse; key the
    -- memo by identity so different parses stay independent
    local invariant_caches = setmetatable({}, {__mode = "k"})
    local function invariants_of(grammar, options)
        if options and options.invariants == false then
            return {}
        end
        local invs = invariant_caches[grammar]
        if not invs then
            invs = automata.grammar_derived_invariants(grammar, options)
            invariant_caches[grammar] = invs
        end
        return invs
    end

    -- returns an invariant proving the word/form is unreachable, or
    -- nil; usable as a certified non-membership check.  A form or
    -- word that exceeds an invariant's proven segment bound is
    -- unreachable by the bound itself (value == nil then).
    function automata.grammar_invariant_excludes(word, grammar, options)
        if type(word) == "string" then
            word = automata.tokenise_word(word)
        end
        for _, inv in ipairs(invariants_of(grammar, options)) do
            local v = invariant_value(inv, word)
            if v == nil or v ~= inv.value then
                return inv
            end
        end
        return nil
    end

    -- true when some invariant proves the form unreachable
    local function invariant_unreachable(invs, form)
        for _, inv in ipairs(invs) do
            local v = invariant_value(inv, form)
            if v == nil or v ~= inv.value then
                return true
            end
        end
        return false
    end

    -- Chomsky normal form (rules A -> BC | A -> a | S -> eps) for a
    -- context-free grammar; returns a plain table with rule lists
    -- {lhs = variable name, rhs = {symbol names}} plus the start symbol
    local function grammar_to_cnf_rules(grammar)
        assert(automata.grammar_is_context_free(grammar))
        local variables, terminals = {}, {}
        for var,_ in pairs(grammar:get_variables()) do
            variables[var] = true
        end
        for sym,_ in pairs(grammar:get_symbols()) do
            -- get_symbols lists all symbols including the variables
            if not variables[sym] then
                terminals[sym] = true
            end
        end
        local start = grammar:get_start_variable()
        local rules = {}
        for rule,_ in pairs(grammar:get_rules()) do
            local rhs = {}
            for i=1,rule.rhs:len() do
                rhs[i] = rule.rhs:get_char(i)
            end
            table.insert(rules, {lhs = rule.lhs:get_char(1), rhs = rhs})
        end

        local function fresh_variable(base)
            local name = base or "Z"
            while variables[name] or terminals[name] do
                name = name .. "'"
            end
            variables[name] = true
            return name
        end

        -- fresh start variable if the start variable occurs on a rhs
        local start_on_rhs = false
        for _, rule in ipairs(rules) do
            for _, sym in ipairs(rule.rhs) do
                if sym == start then
                    start_on_rhs = true
                end
            end
        end
        if start_on_rhs then
            local fresh = fresh_variable(start)
            table.insert(rules, {lhs = fresh, rhs = {start}})
            start = fresh
        end

        -- eliminate epsilon rules (kept only for the start variable)
        local nullable = {}
        local changed = true
        while changed do
            changed = false
            for _, rule in ipairs(rules) do
                local all_null = true
                for _, sym in ipairs(rule.rhs) do
                    if not nullable[sym] then
                        all_null = false
                        break
                    end
                end
                if all_null and not nullable[rule.lhs] then
                    nullable[rule.lhs] = true
                    changed = true
                end
            end
        end
        local eps_rules = {}
        for _, rule in ipairs(rules) do
            local nul_pos = {}
            for i, sym in ipairs(rule.rhs) do
                if nullable[sym] then
                    table.insert(nul_pos, i)
                end
            end
            for mask = 0, 2 ^ #nul_pos - 1 do
                local new_rhs, rest = {}, mask
                for i, sym in ipairs(rule.rhs) do
                    local keep = true
                    for _, pos in ipairs(nul_pos) do
                        if pos == i then
                            keep = rest % 2 == 1
                            rest = math.floor(rest / 2)
                        end
                    end
                    if keep then
                        table.insert(new_rhs, sym)
                    end
                end
                if #new_rhs > 0 or rule.lhs == start then
                    table.insert(eps_rules, {lhs = rule.lhs, rhs = new_rhs})
                end
            end
        end
        rules = eps_rules

        -- eliminate chain rules X -> Y via unit closure
        local reach = {}
        for var,_ in pairs(variables) do
            reach[var] = {[var] = true}
        end
        changed = true
        while changed do
            changed = false
            for _, rule in ipairs(rules) do
                if #rule.rhs == 1 and variables[rule.rhs[1]] then
                    for target,_ in pairs(reach[rule.rhs[1]]) do
                        if not reach[rule.lhs][target] then
                            reach[rule.lhs][target] = true
                            changed = true
                        end
                    end
                end
            end
        end
        local unit_rules = {}
        for _, rule in ipairs(rules) do
            local is_unit = #rule.rhs == 1 and variables[rule.rhs[1]]
            local is_eps = #rule.rhs == 0
            if not is_unit then
                for var,_ in pairs(variables) do
                    if reach[var][rule.lhs] and (not is_eps or var == start) then
                        table.insert(unit_rules, {lhs = var, rhs = rule.rhs})
                    end
                end
            end
        end
        rules = unit_rules

        -- replace terminals in long rules by fresh variables
        local term_var = {}
        for _, rule in ipairs(rules) do
            if #rule.rhs >= 2 then
                for i, sym in ipairs(rule.rhs) do
                    if terminals[sym] then
                        if not term_var[sym] then
                            term_var[sym] = fresh_variable("X")
                            table.insert(rules, {lhs = term_var[sym], rhs = {sym}})
                        end
                        rule.rhs[i] = term_var[sym]
                    end
                end
            end
        end

        -- split rules with rhs longer than 2
        local final_rules = {}
        for _, rule in ipairs(rules) do
            local lhs, rhs = rule.lhs, rule.rhs
            while #rhs > 2 do
                local tail = {}
                for i = 2, #rhs do
                    tail[i - 1] = rhs[i]
                end
                local fresh = fresh_variable("Y")
                table.insert(final_rules, {lhs = lhs, rhs = {rhs[1], fresh}})
                lhs, rhs = fresh, tail
            end
            table.insert(final_rules, {lhs = lhs, rhs = rhs})
        end
        return final_rules, start
    end

    function automata.grammar_to_cnf(grammar)
        local rules, start = grammar_to_cnf_rules(grammar)
        local cnf = {
            start = start,
            eps = false,
            terminals = {},   -- terminal -> set of lhs vars (A -> a)
            pairs = {},       -- B -> C -> set of lhs vars (A -> BC)
            rules = rules,    -- for inspection
        }
        for _, rule in ipairs(rules) do
            if #rule.rhs == 0 then
                cnf.eps = true
            elseif #rule.rhs == 1 then
                local sym = rule.rhs[1]
                cnf.terminals[sym] = cnf.terminals[sym] or {}
                cnf.terminals[sym][rule.lhs] = true
            else
                local b, c = rule.rhs[1], rule.rhs[2]
                cnf.pairs[b] = cnf.pairs[b] or {}
                cnf.pairs[b][c] = cnf.pairs[b][c] or {}
                cnf.pairs[b][c][rule.lhs] = true
            end
        end
        return cnf
    end

    -- CYK parse: the set of left-hand side variables deriving the whole
    -- word (nil for the empty word, where the caller decides via cnf.eps
    -- or a nullable analysis)
    local function cyk_root_set(word, cnf)
        if type(word) == "string" then
            word = automata.tokenise_word(word)
        end
        local n = word:len()
        if n == 0 then
            return nil
        end
        local table_at = {}
        for i = 1, n do
            table_at[i] = {[1] = cnf.terminals[word:get_char(i)] or {}}
        end
        for len = 2, n do
            for i = 1, n - len + 1 do
                local cell = {}
                for k = 1, len - 1 do
                    for b,_ in pairs(table_at[i][k]) do
                        local by_c = cnf.pairs[b]
                        if by_c then
                            for c,_ in pairs(table_at[i + k][len - k]) do
                                local prods = by_c[c]
                                if prods then
                                    for a,_ in pairs(prods) do
                                        cell[a] = true
                                    end
                                end
                            end
                        end
                    end
                end
                table_at[i][len] = cell
            end
        end
        return table_at[1][n]
    end

    -- CYK membership test on a grammar in Chomsky normal form
    function automata.cyk_contains_word(word, cnf)
        if type(word) == "string" then
            word = automata.tokenise_word(word)
        end
        if word:len() == 0 then
            return cnf.eps
        end
        local root = cyk_root_set(word, cnf)
        return root ~= nil and root[cnf.start] == true
    end

    -- stricter than grammar_is_context_free: additionally requires the
    -- lhs to be a real variable. Grammars with a terminal lhs rule
    -- (e.g. a student writing # -> A#B#W where # is not a variable)
    -- are not context-free for CYK purposes -- the BFS handles them.
    local function grammar_is_cyk_safe(grammar)
        local variables = grammar:get_variables()
        for rule,_ in pairs(grammar:get_rules()) do
            if rule.lhs:len() ~= 1 or not variables[rule.lhs:get_char(1)] then
                return false
            end
        end
        return true
    end

    local function prepare_cache_entry_for_word_containment(grammar)
        local grammar_cache = {all={}, words={}, unused_words=util.make_queue(), todo={}}
        if grammar_is_cyk_safe(grammar) then
            -- context-free membership is decided exactly by CYK; the
            -- breadth-first search below remains for word generation
            -- and for grammars with longer or non-variable left-hand
            -- sides
            grammar_cache.cnf = automata.grammar_to_cnf(grammar)
            grammar = automata.remove_null_rules(grammar)
        end
        local start = automata.make_token_sequence()
        start:insert_right_modify(grammar:get_start_variable())
        grammar_cache.all[tostring(grammar:get_start_variable())] = {form = start}
        grammar_cache.todo[tostring(grammar:get_start_variable())] = start
        grammar_cache.contribution = compute_symbol_contributions(grammar)
        grammar_cache.used_grammar = grammar

        -- a lower bound on the length of any terminal word derivable
        -- from a sentential form (math.huge if no word is derivable at
        -- all); it must never overestimate, otherwise
        -- grammar_contains_word could wrongly answer "not contained"
        -- for a word in the language
        function grammar_cache:min_shrink_length(form)
            local min = 0
            for i=1,form:len() do
                local contribution = self.contribution[form:get_char(i)]
                if contribution == math.huge then
                    return math.huge
                end
                min = min + (contribution or 0)
            end
            return min
        end
        return grammar_cache
    end

    function automata.clear_grammar_cache_entry(grammar)
        grammar_caches[tostring(grammar)] = nil
    end

    function automata.grammar_is_context_free(grammar)
        for rule,_ in pairs(grammar:get_rules()) do
            if rule.lhs:len() > 1 then
                return false
            end
        end
        return true
    end

    local function lookup_grammar_cache(grammar)
        local grammar_cache = grammar_caches[tostring(grammar)]
        if not grammar_cache then
            grammar_cache = prepare_cache_entry_for_word_containment(grammar)
            grammar_cache.iter = 1
            grammar_cache.num_words = 0
            grammar_caches[tostring(grammar)] = grammar_cache
        end
        return grammar_cache
    end

    -- breadth-first search over sentential forms; incremental across
    -- calls via grammar_cache (postponed forms rejoin the frontier for
    -- a longer query word). With a word argument returns true/false for
    -- membership, or nil if the iteration caps cut the search before a
    -- definite answer; with word == nil (generator mode) returns a word
    -- of the language or nil when exhausted.
    local function bfs_contains_word(word, grammar_cache, options, record)
        local grammar = grammar_cache.used_grammar
        local iter = grammar_cache.iter
        local result_word
        if not word and grammar_cache.unused_words:len() > 0 then
            return grammar_cache.unused_words:remove_left()
        end
        local word_string
        if word then
            word_string = tostring(word)
        end
        -- when recording a derivation the word itself must have been
        -- generated by this search (with parent pointers); a positive
        -- answer from CYK alone is not enough
        local function word_is_found()
            return grammar_cache.words[word_string] and
                (not record or grammar_cache.all[word_string] ~= nil)
        end
        if word_is_found() then
            return true
        end
        local max_iter = options.max_iter or 200
        local max_words = options.max_words or 200000
        -- max_iter bounds the fresh rounds of *this* call: exploration
        -- done by earlier calls stays in the cache and is not paid
        -- again, so e.g. a generator call after membership checks
        -- still gets its own budget (otherwise it could return nil
        -- -- "looks finite" -- just because the budget was spent).
        -- max_words stays a *global* bound on the total number of
        -- sentential forms explored for this grammar, which is what
        -- actually bounds the overall work.
        local iter_limit = iter + max_iter
        local can_stop = true
        if word then
            for _, check in pairs(grammar_cache.todo) do
                if grammar_cache:min_shrink_length(check) <= word:len() then
                    can_stop = false
                end
            end
        else
            can_stop = false
        end
        local postponed = {}

        -- best-first ordering for the frontier when searching for a
        -- concrete word: forms whose terminals fit the word better are
        -- expanded first. The ordering is deterministic (tie-broken by
        -- the form's string), which also removes the hash-seed lottery
        -- of pairs() traversal between runs. Nothing is ever discarded
        -- -- surplus forms are postponed and rejoin afterwards.
        local word_multiset, grammar_variables
        if word then
            word_multiset = {}
            for i=1,word:len() do
                local c = word:get_char(i)
                word_multiset[c] = (word_multiset[c] or 0) + 1
            end
            grammar_variables = grammar:get_variables()
        end
        local score_cache = {}
        local function forward_score(key, form)
            local cached = score_cache[key]
            if cached then
                return cached
            end
            local excess = 0
            local seen = {}
            for i=1,form:len() do
                local c = form:get_char(i)
                if not grammar_variables[c] then
                    seen[c] = (seen[c] or 0) + 1
                end
            end
            for c,n in pairs(seen) do
                local spare = word_multiset[c] or 0
                if n > spare then
                    excess = excess + n - spare
                end
            end
            score_cache[key] = excess
            return excess
        end
        local max_beam = options.max_beam or 2000

        -- counting invariants of the searched grammar: forms that
        -- violate one can never be reached and are pruned outright;
        -- this shrinks the frontier for grammars whose derivations
        -- wander far outside the useful region first
        local invs = nil
        if options.invariants ~= false then
            if grammar_cache.invariants == nil then
                grammar_cache.invariants =
                    invariants_of(grammar, options)
            end
            invs = grammar_cache.invariants
        end

        -- .all holds every form inspected (also pruned ones), so
        -- num_words alone does not bound memory: check the process
        -- footprint periodically and report a cap instead of dying;
        -- the same flag covers a deadline hit mid-round, since an
        -- interrupted round must keep its unexpanded frontier either
        -- way (dropping it would fake completeness for later calls)
        local mem_full = false
        local seen_count = 0

        while not can_stop and (iter < iter_limit) and (grammar_cache.num_words < max_words)
                and not deadline_expired(options) and not mem_full do
            local new_todo = {}
            local frontier = grammar_cache.todo
            if next(frontier) then
                local count = 0
                for _ in pairs(frontier) do count = count + 1 end
                if count > max_beam then
                    local scored = {}
                    for key, form in pairs(frontier) do
                        scored[#scored + 1] = {key = key, form = form,
                            score = word and forward_score(key, form) or 0}
                    end
                    table.sort(scored, function(a, b)
                        if a.score ~= b.score then
                            return a.score < b.score
                        end
                        local la, lb = a.form:len(), b.form:len()
                        if la ~= lb then
                            return la < lb
                        end
                        return a.key < b.key
                    end)
                    frontier = {}
                    for i=1,max_beam do
                        frontier[scored[i].key] = scored[i].form
                    end
                    for i=max_beam + 1, count do
                        postponed[scored[i].key] = scored[i].form
                    end
                end
            end
            for sequent_key, sequent in pairs(frontier) do
                if mem_full then
                    -- carry the unexpanded sequent over: dropping it
                    -- here would fake an empty frontier for the next
                    -- call, which could then answer "not derivable"
                    -- without having explored it
                    new_todo[sequent_key] = sequent
                else
                    local successors = grammar_word_successors_list(sequent, grammar)
                    for _, succ in ipairs(successors) do
                    local succ_string = tostring(succ)
                    if not grammar_cache.all[succ_string] then
                        seen_count = seen_count + 1
                        if seen_count % 2048 == 0
                                and (grammar_memory_exceeded(options)
                                    or deadline_expired(options)) then
                            mem_full = true
                            break
                        end
                        if invs and invariant_unreachable(invs, succ) then
                            -- provably unreachable: remember only for
                            -- deduplication, never expanded further
                            grammar_cache.all[succ_string] = {form = succ}
                        else
                        grammar_cache.num_words = grammar_cache.num_words + 1
                        if automata.grammar_is_word(succ, grammar) then
                            grammar_cache.words[succ_string] = succ
                            grammar_cache.unused_words:insert_right(succ)
                        end
                        -- record the parent so grammar_derivation can
                        -- reconstruct a derivation later
                        grammar_cache.all[succ_string] = {form = succ, parent = sequent_key}
                        local min = grammar_cache:min_shrink_length(succ)
                        if min == math.huge then
                            -- dead end: no word is derivable from this
                            -- form, for any query; keep it only in .all
                            -- for deduplication
                        elseif word and min > word:len() then
                            postponed[succ_string] = succ
                        else
                            new_todo[succ_string] = succ
                        end
                        end
                    end
                end
                if mem_full then
                    -- a partially expanded sequent goes back on the
                    -- frontier too; its expanded successors are deduped
                    -- by .all on the next attempt anyway, and the
                    -- following sequents land in the carry-over branch
                    new_todo[sequent_key] = sequent
                end
                end
            end
            grammar_cache.todo = new_todo
            -- every form in new_todo already passed the bound check, so
            -- an empty frontier means nothing left worth exploring
            can_stop = next(new_todo) == nil
            if word_is_found() then
                can_stop = true
            end
            if not word and grammar_cache.unused_words:len() > 0 then
                -- generator mode: deliver one word per call
                result_word = grammar_cache.unused_words:remove_left()
                can_stop = true
            end
            iter = iter + 1
        end
        grammar_cache.iter = iter
        for key,value in pairs(postponed) do
            grammar_cache.todo[key] = value
        end
        if word_is_found() then
            return true
        end
        if result_word then
            return result_word
        end
        if not word then
            if can_stop then
                return nil
            end
            return nil, "capped"
        end
        if can_stop then
            -- the remaining forms can provably not reach the word
            return false
        end
        -- hit max_iter/max_words: the word may still be derivable, so
        -- the result is inconclusive; the first return value stays
        -- false for backward compatibility (grading treats it like a
        -- non-member), the second value reports the cap honestly
        return false, "capped"
    end

    -- goal-directed search *backwards* from the word: rules are applied
    -- right-to-left (an occurrence of rule.rhs is replaced by rule.lhs)
    -- until only the start variable remains. Much cheaper than the
    -- forward search when the word is derivable, because it never
    -- explores forms that cannot produce the word.
    --
    -- For a non-contracting grammar (every rule satisfies
    -- |lhs| <= |rhs|) no derivation ever exceeds the word length, so
    -- with max_form_len = word:len() an exhausted frontier *proves*
    -- non-membership. With contracting rules (e.g. A -> λ) the search
    -- is bounded by max_form_len (default 2*|w| + 4); a positive answer
    -- is always a real derivation, a negative one is only conclusive
    -- when nothing was dropped by the length bound.
    local function reverse_contains_word(word, grammar, options)
        local max_iter = options.backward_iter or math.min(options.max_iter or 60, 60)
        -- keep the default budget small: when the backward search can
        -- find the word at all, it typically does so within a few
        -- thousand forms; grammars with erasing rules flood the
        -- frontier with useless insertions and then any extra budget
        -- is wasted time before the forward search takes over
        local max_forms = options.backward_forms or 4000
        local contracting = false
        local reversed = {}
        for rule,_ in pairs(grammar:get_rules()) do
            reversed[#reversed + 1] = {lhs = rule.rhs, rhs = rule.lhs}
            if rule.lhs:len() > rule.rhs:len() then
                contracting = true
            end
        end
        local max_form_len = options.max_form_len
        if not max_form_len then
            if contracting then
                max_form_len = 2 * word:len() + 4
            else
                max_form_len = word:len()
            end
        end
        local start_string = grammar:get_start_variable()
        local word_string = tostring(word)
        local invs = options.invariants ~= false
            and invariants_of(grammar, options) or nil
        -- the seen-set grows with *every* form inspected (also pruned
        -- or length-dropped ones), so num_forms alone does not bound
        -- memory; grammar_memory_exceeded does
        local seen = {[word_string] = true}
        local seen_count = 1
        local frontier = {word}
        local dropped = false
        local num_forms = 1
        local iter = 0
        while iter < max_iter and num_forms < max_forms
                and not deadline_expired(options) do
            iter = iter + 1
            -- deterministic order: shortest (closest to the start
            -- variable) first, ties by string
            table.sort(frontier, function(a, b)
                local la, lb = a:len(), b:len()
                if la ~= lb then
                    return la < lb
                end
                return tostring(a) < tostring(b)
            end)
            local new_frontier = {}
            for _, form in ipairs(frontier) do
                if form:len() == 1 and form:get_char(1) == start_string then
                    return true
                end
                for _, rule in ipairs(reversed) do
                    local matches = automata.grammar_rule_matches(form, rule)
                    for where,_ in pairs(matches) do
                        local succ = automata.grammar_rule_apply(form, rule, where)
                        local succ_string = tostring(succ)
                        if not seen[succ_string] then
                            seen[succ_string] = true
                            seen_count = seen_count + 1
                            if seen_count % 2048 == 0
                                    and (grammar_memory_exceeded(options)
                                        or deadline_expired(options)) then
                                return false, "capped"
                            end
                            if invs and invariant_unreachable(invs, succ) then
                                -- provably unreachable form: not a
                                -- length-bound drop, so it does not
                                -- spoil an exhausted frontier
                            else
                                num_forms = num_forms + 1
                                if succ:len() <= max_form_len then
                                    new_frontier[#new_frontier + 1] = succ
                                else
                                    -- the form exceeds the length bound: the
                                    -- search is incomplete, so a negative
                                    -- answer cannot be trusted
                                    dropped = true
                                end
                            end
                        end
                    end
                end
            end
            if #new_frontier == 0 then
                if dropped or num_forms >= max_forms then
                    return false, "capped"
                end
                -- frontier exhausted without any bound drop: the full
                -- predecessor closure was explored, so the word is
                -- provably not derivable -- for non-contracting
                -- grammars the bound never drops anyway, for
                -- contracting ones an undropped exhaustion is still a
                -- complete (if rare) closure
                return false
            end
            frontier = new_frontier
        end
        return false, "capped"
    end

    function automata.grammar_contains_word(word, grammar, options)
        if word and type(word) == "string" then
            word = automata.tokenise_word(word)
        end
        local grammar_cache = lookup_grammar_cache(grammar)
        if word and grammar_cache.cnf then
            -- context-free grammar: exact answer via CYK, no search caps
            local found = automata.cyk_contains_word(word, grammar_cache.cnf)
            if found and not grammar_cache.words[tostring(word)] then
                grammar_cache.words[tostring(word)] = word
                -- feed the word generator like the breadth-first
                -- search would have, so a later word=nil call does
                -- not conclude "finitely many words" too early
                grammar_cache.unused_words:insert_right(word)
            end
            return found
        end
        if word then
            -- a violated counting invariant is a certificate of
            -- non-membership -- no search at all needed
            if (not options or options.invariants ~= false)
                and automata.grammar_invariant_excludes(word, grammar,
                                                       options) then
                return false
            end
            -- unrestricted grammar: try the goal-directed backward
            -- search first -- it is much faster on derivable words and
            -- proves non-membership for non-contracting grammars
            local back, capped = reverse_contains_word(word, grammar, options or {})
            if back then
                grammar_cache.words[tostring(word)] = word
                return true
            end
            if not capped then
                -- non-contracting grammar, frontier exhausted: proven
                return false
            end
        end
        return bfs_contains_word(word, grammar_cache, options or {})
    end

    -- a derivation of the word, as a list of sentential forms from the
    -- start variable to the word, or nil if the word is not derivable
    -- (within the search caps); uses the breadth-first search even for
    -- context-free grammars since CYK does not record the steps
    function automata.grammar_derivation(word, grammar, options)
        if type(word) == "string" then
            word = automata.tokenise_word(word)
        end
        local grammar_cache = lookup_grammar_cache(grammar)
        if grammar_cache.cnf and not automata.cyk_contains_word(word, grammar_cache.cnf) then
            -- context-free non-member: CYK proves this exactly, no
            -- need to burn the breadth-first search budget
            return nil
        end
        if bfs_contains_word(word, grammar_cache, options or {}, true) ~= true then
            return nil
        end
        local steps = {}
        local entry = grammar_cache.all[tostring(word)]
        while entry do
            table.insert(steps, 1, entry.form)
            entry = entry.parent and grammar_cache.all[entry.parent]
        end
        return steps
    end

    -- == language comparison =============================================
    --
    -- Equality of grammar languages is undecidable in general, so
    -- grammar_compare_languages combines several *sound* but incomplete
    -- methods: proven "=" (alpha-equivalent grammars, exact DFA
    -- comparison for linear grammars, both-provably-empty for
    -- context-free), proven "!="/">"/"<" (a verified counterexample
    -- word), and nil when nothing is decided within the search caps.

    -- "right" when every rule is A -> t* [V], "left" for A -> [V] t*,
    -- nil otherwise; the lhs must be a single variable either way
    local function grammar_linear_form(grammar)
        local variables = grammar:get_variables()
        local right, left = true, true
        for rule,_ in pairs(grammar:get_rules()) do
            if rule.lhs:len() ~= 1 or not variables[rule.lhs:get_char(1)] then
                return nil
            end
            for i = 1, rule.rhs:len() do
                if variables[rule.rhs:get_char(i)] then
                    if i ~= rule.rhs:len() then
                        right = false
                    end
                    if i ~= 1 then
                        left = false
                    end
                end
            end
        end
        if right then
            return "right"
        end
        if left then
            return "left"
        end
        return nil
    end

    -- NFA for a linear grammar. Right-linear A -> t* [V]: variables
    -- are states with S initial, terminal rules end in a fresh
    -- accepting state, A -> eps makes A accepting. Left-linear
    -- A -> [V] t*: a fresh state is initial, transitions run into the
    -- lhs variable (B -t*-> A for A -> Bt*, initial -t*-> A for
    -- A -> t*), and only S accepts.
    function automata.grammar_to_nfa(grammar, left_linear)
        local variables = grammar:get_variables()
        local symbols = grammar:get_symbols()
        local nfa = automata.make_nfa(true)
        local function fresh_name(base)
            while variables[base] or symbols[base] do
                base = base .. "'"
            end
            return base
        end
        local chain_number = 0
        local function chain_state()
            local name
            repeat
                chain_number = chain_number + 1
                name = "qc" .. chain_number
            until not variables[name] and not symbols[name]
            return name
        end
        for var,_ in pairs(variables) do
            nfa:add_state(var)
        end
        for sym,_ in pairs(symbols) do
            if not variables[sym] then
                nfa:add_symbol(sym)
            end
        end
        -- a start variable that is not actually a variable of the
        -- grammar (parse_rules defaults to "S") generates nothing, so
        -- the language is empty and the start state stays unreachable
        local start = grammar:get_start_variable()
        if not variables[start] then
            start = fresh_name("qs")
            nfa:add_state(start)
        end
        local final, initial
        if left_linear then
            initial = fresh_name("qi")
            nfa:add_state(initial)
            nfa:set_initial(initial, true)
            nfa:set_accepting(start, true)
        else
            final = fresh_name("qf")
            nfa:add_state(final)
            nfa:set_accepting(final, true)
            nfa:set_initial(start, true)
        end
        for rule,_ in pairs(grammar:get_rules()) do
            local lhs = rule.lhs:get_char(1)
            local rhs = {}
            for i = 1, rule.rhs:len() do
                rhs[i] = rule.rhs:get_char(i)
            end
            -- from/to are the variable ends of the rule, rhs keeps only
            -- the terminal part in reading order
            local from, to
            if left_linear then
                to = lhs
                if #rhs > 0 and variables[rhs[1]] then
                    from = table.remove(rhs, 1)      -- A -> B t*
                else
                    from = initial                   -- A -> t*
                end
            else
                from = lhs
                if #rhs > 0 and variables[rhs[#rhs]] then
                    to = table.remove(rhs)           -- A -> t* B
                else
                    to = final                       -- A -> t*
                end
            end
            if #rhs == 0 then
                if variables[to] then
                    -- unit rule, or eps rule of a left-linear grammar
                    -- (initial -> A)
                    nfa:add_transition(from, "", to)
                else
                    nfa:set_accepting(from, true)   -- A -> eps
                end
            else
                local current = from
                for i, sym in ipairs(rhs) do
                    local next_state = to
                    if i < #rhs then
                        next_state = chain_state()
                        nfa:add_state(next_state)
                    end
                    nfa:add_transition(current, sym, next_state)
                    current = next_state
                end
            end
        end
        return nfa
    end

    -- enumerate all words of length <= max_length; returns (set,
    -- complete) where the set maps word strings to token sequences and
    -- complete tells whether the enumeration is provably complete for
    -- the bound: every not-expanded sentential form has a minimum
    -- derivable length above max_length, so no such word was missed
    function automata.grammar_enumerate_words(grammar, max_length, options)
        options = options or {}
        local grammar_cache = lookup_grammar_cache(grammar)
        local used = grammar_cache.used_grammar
        local max_iter = options.max_iter or 200
        local max_words = options.max_words or 200000
        local postponed = {}
        local complete = false
        local mem_full = false
        local invs = options.invariants ~= false
            and invariants_of(used, options) or nil
        while grammar_cache.iter <= max_iter and grammar_cache.num_words < max_words
                and not deadline_expired(options) and not mem_full do
            local new_todo = {}
            local progressed = false
            for key, sequent in pairs(grammar_cache.todo) do
                if grammar_cache:min_shrink_length(sequent) <= max_length then
                    for _, succ in ipairs(grammar_word_successors_list(sequent, used)) do
                        local succ_string = tostring(succ)
                        if not grammar_cache.all[succ_string] then
                            progressed = true
                            grammar_cache.all[succ_string] = {form = succ, parent = key}
                            if invs and invariant_unreachable(invs, succ) then
                                -- provably unreachable: dedup only
                            else
                            grammar_cache.num_words = grammar_cache.num_words + 1
                            if automata.grammar_is_word(succ, used) then
                                grammar_cache.words[succ_string] = succ
                                grammar_cache.unused_words:insert_right(succ)
                            end
                            if grammar_cache:min_shrink_length(succ) <= max_length then
                                new_todo[succ_string] = succ
                            else
                                -- keep for later calls with a bigger
                                -- bound, like bfs_contains_word does
                                postponed[succ_string] = succ
                            end
                            if grammar_cache.num_words % 2048 == 0
                                    and (grammar_memory_exceeded(options)
                                        or deadline_expired(options)) then
                                mem_full = true
                                break
                            end
                            end
                        end
                    end
                    if mem_full then
                        break
                    end
                else
                    -- provably cannot reach a word of length <=
                    -- max_length; keep it for later, bigger bounds
                    postponed[key] = sequent
                end
            end
            grammar_cache.todo = new_todo
            grammar_cache.iter = grammar_cache.iter + 1
            if not progressed then
                complete = true
                break
            end
        end
        for key, form in pairs(postponed) do
            grammar_cache.todo[key] = form
        end
        -- every word ever discovered (by enumeration, membership search
        -- or CYK) counts; only the length bound decides inclusion here
        local found = {}
        for word_string, word in pairs(grammar_cache.words) do
            if word:len() <= max_length then
                found[word_string] = word
            end
        end
        return found, complete
    end

    -- yield-first variant of grammar_enumerate_words: the frontier is
    -- processed ordered by the minimum terminal yield of each form
    -- (bucket queue over min_shrink 0..max_length), so short words
    -- reached through long mutual recursion are found even when the
    -- sentential-form space explodes breadth-first.  Forms whose lower
    -- bound already exceeds max_length are discarded (sound: they can
    -- never yield a shorter word).  max_forms bounds the total number
    -- of distinct forms expanded; returns the word map and whether the
    -- search completed within the bound.
    function automata.grammar_enumerate_words_yieldfirst(grammar,
                                                         max_length,
                                                         options)
        options = options or {}
        local max_forms = options.max_forms or options.max_words
            or 200000
        -- memory is a resource bound like the form count: a form
        -- storm must report "incomplete" rather than take the whole
        -- process down -- callers may then still use the words found
        -- or escalate within a different budget
        local contribution = compute_symbol_contributions(grammar)
        local used = grammar
        -- only grammars with terminals on a left-hand side can rewrite
        -- an already terminal-only form into a further word; for
        -- context-free grammars words are sinks
        local terminal_lhs = false
        for rule,_ in pairs(used:get_rules()) do
            for i = 1, rule.lhs:len() do
                if not used:has_variable(rule.lhs:get_char(i)) then
                    terminal_lhs = true
                    break
                end
            end
            if terminal_lhs then
                break
            end
        end
        local function min_shrink(form)
            local min = 0
            for i = 1, form:len() do
                local c = contribution[form:get_char(i)]
                if c == math.huge then
                    return math.huge
                end
                min = min + (c or 0)
            end
            return min
        end
        local invs = options.invariants ~= false
            and invariants_of(used, options) or nil
        local start = automata.make_token_sequence()
        start:insert_right_modify(grammar:get_start_variable())
        local seen, words = {}, {}
        local buckets = {}
        local function push(form, bound)
            if bound > max_length then
                return
            end
            local bucket = buckets[bound]
            if not bucket then
                bucket = {head = 1, tail = 0}
                buckets[bound] = bucket
            end
            bucket.tail = bucket.tail + 1
            bucket[bucket.tail] = form
        end
        local count = 0
        local complete = true
        seen[tostring(start)] = true
        local b0 = min_shrink(start)
        if b0 <= max_length then
            push(start, b0)
        end
        -- round robin over the bound buckets with a small uniform
        -- quota: low bounds go first every pass, but no bound may
        -- starve -- a contracting rule can make one bucket refill
        -- itself indefinitely, and a single bucket's unchecked quota
        -- would burn the whole form budget before other bounds run
        local quantum = 16
        while count < max_forms and not deadline_expired(options) do
            local any = false
            for b = 0, max_length do
                local bucket = buckets[b]
                if bucket and bucket.head <= bucket.tail then
                    any = true
                    local q = quantum
                    while q > 0 and bucket.head <= bucket.tail do
                        q = q - 1
                        -- FIFO within a bucket: the oldest form first,
                        -- or a self-refilling bucket would bury the
                        -- shallow forms under its own flood
                        local form = bucket[bucket.head]
                        bucket[bucket.head] = nil
                        bucket.head = bucket.head + 1
                        if os.getenv("YF_DEBUG") then io.stderr:write(
                            "pop b=" .. b .. " form=" .. tostring(form) .. "\n") end
                        for _, succ in ipairs(
                            grammar_word_successors_list(form, used)) do
                            local s = tostring(succ)
                            if not seen[s] then
                                seen[s] = true
                                count = count + 1
                                if not (invs and invariant_unreachable(
                                        invs, succ)) then
                                    local word = automata.grammar_is_word(
                                        succ, used)
                                    if word and succ:len() <= max_length then
                                        words[s] = succ
                                    end
                                    if not word or terminal_lhs then
                                        push(succ, min_shrink(succ))
                                    end
                                end
                                if count >= max_forms then
                                    complete = false
                                    return words, complete
                                end
                                if count % 2048 == 0
                                    and (grammar_memory_exceeded(options)
                                        or deadline_expired(options)) then
                                    return words, false
                                end
                            end
                        end
                    end
                end
            end
            if os.getenv("YF_DEBUG") then
                local occ = {}
                for b2 = 0, max_length do
                    local bk = buckets[b2]
                    occ[#occ + 1] = b2 .. ":" ..
                        (bk and (bk.tail - bk.head + 1) or 0)
                end
                io.stderr:write("pass end count=" .. count .. " " ..
                    table.concat(occ, " ") .. "\n")
            end
            if not any then
                break
            end
        end
        if count >= max_forms or deadline_expired(options) then
            complete = false
        end
        return words, complete
    end

    -- proven-true if the grammars differ only by variable names; the
    -- backtracking search is capped, so nil means "could not decide"
    -- rather than "different"
    function automata.grammars_alpha_equivalent(grammar1, grammar2)
        local vars1, vars2 = {}, {}
        local in_vars2 = {}
        for var,_ in pairs(grammar1:get_variables()) do
            vars1[#vars1 + 1] = var
        end
        for var,_ in pairs(grammar2:get_variables()) do
            vars2[#vars2 + 1] = var
            in_vars2[var] = true
        end
        if #vars1 ~= #vars2 then
            return false
        end
        -- terminal alphabets must be identical
        local symbols1 = grammar1:get_symbols()
        local symbols2 = grammar2:get_symbols()
        local variables1 = grammar1:get_variables()
        local num_terminals = 0
        for sym,_ in pairs(symbols1) do
            if not variables1[sym] then
                num_terminals = num_terminals + 1
                if not symbols2[sym] or in_vars2[sym] then
                    return false
                end
            end
        end
        for sym,_ in pairs(symbols2) do
            if not in_vars2[sym] then
                num_terminals = num_terminals - 1
            end
        end
        if num_terminals ~= 0 then
            return false
        end

        -- a rule skeleton replaces variables by "?", so occurrence
        -- signatures of mappable variables are identical
        local function skeleton(seq, grammar)
            local variables = grammar:get_variables()
            local parts = {}
            for i = 1, seq:len() do
                local sym = seq:get_char(i)
                parts[i] = variables[sym] and "?" or sym
            end
            return table.concat(parts, " ")
        end
        local function rule_skeleton(rule, grammar)
            return skeleton(rule.lhs, grammar) .. "->" .. skeleton(rule.rhs, grammar)
        end

        local function var_signature(var, grammar)
            local occ = {}
            for rule,_ in pairs(grammar:get_rules()) do
                local skel = rule_skeleton(rule, grammar)
                for i = 1, rule.lhs:len() do
                    if rule.lhs:get_char(i) == var then
                        occ[#occ + 1] = skel .. "|l" .. i
                    end
                end
                for i = 1, rule.rhs:len() do
                    if rule.rhs:get_char(i) == var then
                        occ[#occ + 1] = skel .. "|r" .. i
                    end
                end
            end
            table.sort(occ)
            return table.concat(occ, ";")
        end

        -- start symbols must map onto each other
        local start1 = grammar1:get_start_variable()
        local start2 = grammar2:get_start_variable()
        if var_signature(start1, grammar1) ~= var_signature(start2, grammar2) then
            return false
        end

        local candidates = {}
        for _, v1 in ipairs(vars1) do
            local sig = var_signature(v1, grammar1)
            local list = {}
            for _, v2 in ipairs(vars2) do
                if var_signature(v2, grammar2) == sig then
                    list[#list + 1] = v2
                end
            end
            if #list == 0 then
                return false
            end
            candidates[v1] = list
        end
        -- most constrained variables first
        table.sort(vars1, function(a, b) return #candidates[a] < #candidates[b] end)

        local budget = 100000
        local function verify(mapping)
            local seen = {}
            local count = 0
            for rule,_ in pairs(grammar1:get_rules()) do
                count = count + 1
                local lhs_parts, rhs_parts = {}, {}
                for i = 1, rule.lhs:len() do
                    local sym = rule.lhs:get_char(i)
                    lhs_parts[i] = mapping[sym] or sym
                end
                for i = 1, rule.rhs:len() do
                    local sym = rule.rhs:get_char(i)
                    rhs_parts[i] = mapping[sym] or sym
                end
                seen[table.concat(lhs_parts, " ") .. "->" .. table.concat(rhs_parts, " ")] = true
            end
            for rule,_ in pairs(grammar2:get_rules()) do
                count = count - 1
                local lhs_parts, rhs_parts = {}, {}
                for i = 1, rule.lhs:len() do
                    lhs_parts[i] = rule.lhs:get_char(i)
                end
                for i = 1, rule.rhs:len() do
                    rhs_parts[i] = rule.rhs:get_char(i)
                end
                local key = table.concat(lhs_parts, " ") .. "->" .. table.concat(rhs_parts, " ")
                if not seen[key] then
                    return false
                end
            end
            return count == 0
        end

        local mapping = { [start1] = start2 }
        local used = { [start2] = true }
        local order = {}
        for _, v in ipairs(vars1) do
            if v ~= start1 then
                order[#order + 1] = v
            end
        end

        local function assign(i)
            if i > #order then
                return verify(mapping)
            end
            local v1 = order[i]
            for _, v2 in ipairs(candidates[v1]) do
                budget = budget - 1
                if budget < 0 then
                    return nil
                end
                if not used[v2] then
                    mapping[v1] = v2
                    used[v2] = true
                    local result = assign(i + 1)
                    if result ~= false then
                        return result
                    end
                    mapping[v1] = nil
                    used[v2] = nil
                end
            end
            return false
        end
        return assign(1)
    end

    -- reduce a context-free grammar to a canonical kernel by applying
    -- only language-preserving transformations, so that grammars
    -- differing merely in presentation collapse to alpha-equivalent
    -- kernels:
    --   * rules of unproductive variables (can never reach a terminal
    --     word) and rules of unreachable variables are dropped
    --   * a variable defined by a single production is inlined into
    --     every right-hand side occurrence (skipped when the
    --     production mentions the variable itself, which would loop)
    --   * variables with literally identical production sets are merged
    --     into one representative (sound: identical equations have the
    --     same least fixpoint in each component)
    -- Every step preserves the generated language. Returns the
    -- simplified rule list and start variable, or nil for grammars that
    -- are not context-free in the strict sense (non-variable or longer
    -- left-hand sides), where these transformations are unsafe.
    local function normalized_rules(grammar)
        if not grammar_is_cyk_safe(grammar) then
            return nil
        end
        local variables = grammar:get_variables()
        local start = grammar:get_start_variable()
        local rules = {}
        local seen = {}
        for rule,_ in pairs(grammar:get_rules()) do
            local rhs = {}
            for i=1,rule.rhs:len() do
                rhs[i] = rule.rhs:get_char(i)
            end
            -- the rule set may hold object-level duplicates; semantically
            -- identical productions must collapse or inline_singles would
            -- never see a variable as single-production
            local key = rule.lhs:get_char(1) .. "\x1e" .. table.concat(rhs, "\x1f")
            if not seen[key] then
                seen[key] = true
                rules[#rules + 1] = {lhs = rule.lhs:get_char(1), rhs = rhs}
            end
        end
        -- deterministic processing order: the fixpoint below should not
        -- depend on pairs() hash order
        table.sort(rules, function(a, b)
            if a.lhs ~= b.lhs then
                return a.lhs < b.lhs
            end
            return table.concat(a.rhs, " ") < table.concat(b.rhs, " ")
        end)

        local function rhs_key(rhs)
            return table.concat(rhs, "\x1f")
        end

        -- drop rules mentioning unproductive variables, and rules
        -- whose left-hand side is unreachable from the start variable;
        -- the two are recomputed to a fixpoint because pruning can
        -- create new violations of either kind
        local function prune()
            local changed = true
            while changed do
                changed = false
                local productive = {}
                local progress = true
                while progress do
                    progress = false
                    for _, rule in ipairs(rules) do
                        if not productive[rule.lhs] then
                            local ok = true
                            for _, sym in ipairs(rule.rhs) do
                                if variables[sym] and not productive[sym] then
                                    ok = false
                                    break
                                end
                            end
                            if ok then
                                productive[rule.lhs] = true
                                progress = true
                            end
                        end
                    end
                end
                local kept = {}
                for _, rule in ipairs(rules) do
                    local ok = productive[rule.lhs]
                    if ok then
                        for _, sym in ipairs(rule.rhs) do
                            if variables[sym] and not productive[sym] then
                                ok = false
                                break
                            end
                        end
                    end
                    if ok then
                        kept[#kept + 1] = rule
                    else
                        changed = true
                    end
                end
                rules = kept
                local reachable = {[start] = true}
                progress = true
                while progress do
                    progress = false
                    for _, rule in ipairs(rules) do
                        if reachable[rule.lhs] then
                            for _, sym in ipairs(rule.rhs) do
                                if variables[sym] and not reachable[sym] then
                                    reachable[sym] = true
                                    progress = true
                                end
                            end
                        end
                    end
                end
                kept = {}
                for _, rule in ipairs(rules) do
                    if reachable[rule.lhs] then
                        kept[#kept + 1] = rule
                    else
                        changed = true
                    end
                end
                rules = kept
            end
        end

        -- inline variables with exactly one production; the production
        -- must not mention the variable itself
        local function inline_singles()
            local singles = {}
            for _, rule in ipairs(rules) do
                singles[rule.lhs] = (singles[rule.lhs] or 0) + 1
            end
            local candidates = {}
            for var,_ in pairs(singles) do
                candidates[#candidates + 1] = var
            end
            table.sort(candidates)
            for _, var in ipairs(candidates) do
                local rule
                for _, r in ipairs(rules) do
                    if r.lhs == var then
                        rule = r
                        break
                    end
                end
                if var ~= start and singles[var] == 1 and rule then
                    local self_ref = false
                    for _, sym in ipairs(rule.rhs) do
                        if sym == var then
                            self_ref = true
                            break
                        end
                    end
                    if not self_ref then
                        for _, other in ipairs(rules) do
                            if other ~= rule then
                                local rhs = {}
                                for _, sym in ipairs(other.rhs) do
                                    if sym == var then
                                        for _, s in ipairs(rule.rhs) do
                                            rhs[#rhs + 1] = s
                                        end
                                    else
                                        rhs[#rhs + 1] = sym
                                    end
                                end
                                other.rhs = rhs
                            end
                        end
                        return rule -- remove one per round, then retry
                    end
                end
            end
            return nil
        end

        -- merge variables whose production sets are literally
        -- identical (X -> BB twice under two names, or Y -> aX | b
        -- delegating to the representative X). The sets must match
        -- token for token: collapsing the pair under a renaming would
        -- be unsound -- X -> aY | bb with Y -> aX | b look equal after
        -- collapsing but generate different languages, since the
        -- recursion passes through the pair
        local function merge_identical()
            local productions = {}
            for _, rule in ipairs(rules) do
                productions[rule.lhs] = productions[rule.lhs] or {}
                productions[rule.lhs][rhs_key(rule.rhs)] = true
            end
            local order = {}
            for var,_ in pairs(productions) do
                order[#order + 1] = var
            end
            table.sort(order)
            for _, var in ipairs(order) do
                if var ~= start and productions[var] then
                    local rep = nil
                    for _, other in ipairs(order) do
                        if other ~= var and productions[other] then
                            local a, b = productions[var], productions[other]
                            local equal = true
                            for k,_ in pairs(a) do
                                if not b[k] then equal = false break end
                            end
                            for k,_ in pairs(b) do
                                if not a[k] then equal = false break end
                            end
                            if equal then
                                rep = other
                                break
                            end
                        end
                    end
                    if rep then
                        for _, rule in ipairs(rules) do
                            if rule.lhs == var then
                                rule.dead = true
                            else
                                for i, sym in ipairs(rule.rhs) do
                                    if sym == var then
                                        rule.rhs[i] = rep
                                    end
                                end
                            end
                        end
                        return true
                    end
                end
            end
            return false
        end

        local function sweep_dead()
            local kept = {}
            for _, rule in ipairs(rules) do
                if not rule.dead then
                    kept[#kept + 1] = rule
                end
            end
            rules = kept
        end

        -- normalize: prune, then simplify to a fixpoint, prune again
        prune()
        local guard = 0
        while guard < 200 do
            guard = guard + 1
            local inlined = inline_singles()
            if inlined then
                inlined.dead = true
                sweep_dead()
            elseif merge_identical() then
                sweep_dead()
            else
                break
            end
        end
        prune()
        return {rules = rules, start = start}
    end

    -- rebuild a grammar object from a rule list {lhs = string,
    -- rhs = {string, ...}}; token sequences are assembled directly
    -- because add_rule on a string would re-tokenise, splitting
    -- multi-character tokens and turning separators into terminals
    local function rules_to_grammar(rule_list, start)
        local g = automata.make_grammar()
        g:set_start_variable(start)
        for _, rule in ipairs(rule_list) do
            local lhs = automata.make_token_sequence()
            lhs:insert_right_modify(rule.lhs)
            local rhs = automata.make_token_sequence()
            for _, sym in ipairs(rule.rhs) do
                rhs:insert_right_modify(sym)
            end
            g:add_rule(lhs, rhs)
        end
        return g
    end

    -- full normalisation: language-preserving simplifications, then
    -- Chomsky normal form, then a final merge pass over the fresh helper
    -- variables that binarisation introduced
    local function normalized_rule_kernel(grammar)
        local base = normalized_rules(grammar)
        if not base then
            return nil
        end
        local rebuilt = rules_to_grammar(base.rules, base.start)
        local cnf_rules, cnf_start = grammar_to_cnf_rules(rebuilt)
        -- merge variables whose production sets are literally
        -- identical; the sets are rebuilt each round because a merge
        -- substitutes the representative in right-hand sides, which can
        -- make further production sets equal
        local merged = true
        local guard = 0
        while merged and guard < 100 do
            merged = false
            guard = guard + 1
            local productions = {}
            for _, rule in ipairs(cnf_rules) do
                productions[rule.lhs] = productions[rule.lhs] or {}
                productions[rule.lhs][table.concat(rule.rhs, "\x1f")] = true
            end
            local order = {}
            for var,_ in pairs(productions) do
                order[#order + 1] = var
            end
            table.sort(order)
            for _, var in ipairs(order) do
                if var ~= cnf_start then
                    local rep = nil
                    for _, other in ipairs(order) do
                        if other ~= var then
                            local a, b = productions[var], productions[other]
                            local equal = true
                            for k,_ in pairs(a) do
                                if not b[k] then equal = false break end
                            end
                            for k,_ in pairs(b) do
                                if not a[k] then equal = false break end
                            end
                            if equal then
                                rep = other
                                break
                            end
                        end
                    end
                    if rep then
                        local kept = {}
                        for _, rule in ipairs(cnf_rules) do
                            if rule.lhs ~= var then
                                for i, sym in ipairs(rule.rhs) do
                                    if sym == var then
                                        rule.rhs[i] = rep
                                    end
                                end
                                kept[#kept + 1] = rule
                            end
                        end
                        cnf_rules = kept
                        merged = true
                        break
                    end
                end
            end
        end
        return {rules = cnf_rules, start = cnf_start}
    end

    -- proven true when the language-preserving normalisation above
    -- produces alpha-equivalent kernels; nil when it does not apply
    -- (non-context-free grammar). false means the kernels differ,
    -- which does NOT prove the languages differ -- treat it like nil
    function automata.grammar_normalized_equal(grammar1, grammar2)
        local k1 = normalized_rule_kernel(grammar1)
        local k2 = normalized_rule_kernel(grammar2)
        if not k1 or not k2 then
            return nil
        end
        return automata.grammars_alpha_equivalent(
            rules_to_grammar(k1.rules, k1.start),
            rules_to_grammar(k2.rules, k2.start))
    end

    -- nullable variables of a {lhs, rhs={...}} rule list; in a
    -- context-free rule list the variables are exactly the symbols
    -- occurring on some left-hand side
    local function nullable_vars(rule_list)
        local vars = {}
        for _, rule in ipairs(rule_list) do
            vars[rule.lhs] = true
        end
        local nullable = {}
        local changed = true
        while changed do
            changed = false
            for _, rule in ipairs(rule_list) do
                if not nullable[rule.lhs] then
                    local all_null = true
                    for _, sym in ipairs(rule.rhs) do
                        if not vars[sym] or not nullable[sym] then
                            all_null = false
                            break
                        end
                    end
                    if all_null then
                        nullable[rule.lhs] = true
                        changed = true
                    end
                end
            end
        end
        return nullable
    end

    -- Try to prove L(sub) is contained in L(sup) by rule simulation:
    -- find a map f from the variables of sub to nonempty products of
    -- sup variables (single variables when max_product = 1) with
    -- f(start_sub) = start_sup such that every rule X -> beta of sub
    -- satisfies f(X) =>* f(beta) in sup. Such a map transfers every
    -- derivation tree of sub into one of sup, so L(sub) <= L(sup)
    -- follows -- a variable may thus be embedded as a product of
    -- others, which catches congruences that no variable-to-variable
    -- map can express. The derivability check is exact: in an
    -- augmented grammar where each sup variable V may also terminate
    -- as a marker terminal and each used product gets a helper
    -- variable P -> Y Z ..., f(X) =>* f(beta) is decided by CYK.
    -- Returns true (inclusion proven), false/nil (no map found).
    local function grammar_simulates(sub_kernel, sup_kernel, max_product)
        -- sup vars and augmented grammar; the start variable counts as
        -- a variable even when it has no rules left (empty language)
        local sup_vars = {[sup_kernel.start] = true}
        for _, rule in ipairs(sup_kernel.rules) do
            sup_vars[rule.lhs] = true
        end
        -- the empty language is contained in every language
        if #sub_kernel.rules == 0 then
            return true
        end
        -- nothing but the empty language simulates into it
        if #sup_kernel.rules == 0 then
            return false
        end

        -- min-yield filter: L(X) <= L(f(X)) requires f(X) to reach a
        -- terminal word at most as long as the shortest word of X;
        -- for products the component minima add up
        local sub_grammar = rules_to_grammar(sub_kernel.rules, sub_kernel.start)
        local sup_grammar = rules_to_grammar(sup_kernel.rules, sup_kernel.start)
        local my_sub = minimum_terminal_yields(sub_grammar)
        local my_sup = minimum_terminal_yields(sup_grammar)

        local sup_var_list = {}
        for y,_ in pairs(sup_vars) do
            sup_var_list[#sup_var_list + 1] = y
        end
        table.sort(sup_var_list)
        max_product = max_product or 1

        -- in a pruned context-free rule list the variables are exactly
        -- the symbols occurring on some left-hand side
        local sub_vars_list = {}
        local sub_var_set = {}
        for _, rule in ipairs(sub_kernel.rules) do
            if not sub_var_set[rule.lhs] then
                sub_var_set[rule.lhs] = true
                sub_vars_list[#sub_vars_list + 1] = rule.lhs
            end
        end
        table.sort(sub_vars_list)

        -- candidate images per sub var: variable products of length
        -- 1..max_product filtered by min-yield, shortest first
        local candidates_cache = {}
        local function candidates(x)
            if candidates_cache[x] then
                return candidates_cache[x]
            end
            local cands = {}
            local bound = my_sub[x] or math.huge
            local function gen(depth, acc, acc_yield)
                if #acc >= 1 and acc_yield <= bound then
                    cands[#cands + 1] = acc
                end
                if depth < max_product then
                    for _, y in ipairs(sup_var_list) do
                        local ys = my_sup[y] or math.huge
                        if acc_yield + ys <= bound then
                            local nacc = {}
                            for _, s in ipairs(acc) do nacc[#nacc + 1] = s end
                            nacc[#nacc + 1] = y
                            gen(depth + 1, nacc, acc_yield + ys)
                        end
                    end
                end
            end
            gen(0, {}, 0)
            -- the empty product maps a variable to the empty word;
            -- sound: epsilon =>* f(beta) forces f(beta) empty, so
            -- only variables that can produce nothing but lambda
            -- accept it
            cands[#cands + 1] = {}
            table.sort(cands, function(a, b)
                if #a ~= #b then return #a < #b end
                return table.concat(a, "\0") < table.concat(b, "\0")
            end)
            candidates_cache[x] = cands
            return cands
        end

        -- augmented sup grammar: original rules, a marker terminal per
        -- variable, plus one helper variable per product that any
        -- candidate list mentions
        local aug = automata.make_grammar()
        aug:set_start_variable(sup_kernel.start)
        local marker = {}
        for var,_ in pairs(sup_vars) do
            marker[var] = "\x01" .. var
            aug:add_symbol(marker[var])
        end
        local prod_name, prod_of = {}, {}
        local prod_counter = 0
        local function product_var(seq)
            if #seq == 1 then
                return seq[1]
            end
            local key = table.concat(seq, "\0")
            if not prod_name[key] then
                prod_counter = prod_counter + 1
                local name = "Q\0" .. prod_counter
                prod_name[key] = name
                prod_of[name] = seq
            end
            return prod_name[key]
        end
        for _, x in ipairs(sub_vars_list) do
            for _, seq in ipairs(candidates(x)) do
                product_var(seq)
            end
        end
        product_var({sup_kernel.start})
        for _, rule in ipairs(sup_kernel.rules) do
            local lhs = automata.make_token_sequence()
            lhs:insert_right_modify(rule.lhs)
            local rhs = automata.make_token_sequence()
            for _, sym in ipairs(rule.rhs) do
                rhs:insert_right_modify(sym)
            end
            aug:add_rule(lhs, rhs)
        end
        for var,_ in pairs(sup_vars) do
            local lhs = automata.make_token_sequence()
            lhs:insert_right_modify(var)
            local mark = automata.make_token_sequence()
            mark:insert_right_modify(marker[var])
            aug:add_rule(lhs, mark)
        end
        for name, seq in pairs(prod_of) do
            local lhs = automata.make_token_sequence()
            lhs:insert_right_modify(name)
            aug:add_variable(name)
            local rhs = automata.make_token_sequence()
            for _, sym in ipairs(seq) do
                rhs:insert_right_modify(sym)
            end
            aug:add_rule(lhs, rhs)
        end
        local aug_cnf = automata.grammar_to_cnf(aug)
        local sup_nullable = nullable_vars(sup_kernel.rules)

        -- the map under construction: var -> nonempty sequence of
        -- sup variables; the start symbol is forced to the start
        -- variable itself
        local assign = {[sub_kernel.start] = {sup_kernel.start}}

        -- a product image is nullable iff every component is
        local function image_nullable(img)
            for _, y in ipairs(img) do
                if not sup_nullable[y] then
                    return false
                end
            end
            return true
        end

        -- CYK check: does f(X)=lhs_img derive f(rhs) in the augmented
        -- sup? lhs_img is the product f maps the lhs variable to
        local verify_cache = {}
        local function verifies(lhs_img, rhs)
            -- returns true iff f(X)=lhs_img derives f(rhs) in aug
            if #rhs == 0 then
                return image_nullable(lhs_img)
            end
            local word = automata.make_token_sequence()
            for _, sym in ipairs(rhs) do
                if sub_var_set[sym] then
                    for _, comp in ipairs(assign[sym]) do
                        word:insert_right_modify(marker[comp])
                    end
                else
                    word:insert_right_modify(sym)
                end
            end
            -- f(rhs) collapsed to lambda (all images empty)
            if word:len() == 0 then
                return image_nullable(lhs_img)
            end
            local key = table.concat(lhs_img, "\0") .. "\1" .. tostring(word)
            local cached = verify_cache[key]
            if cached ~= nil then
                return cached
            end
            local root = cyk_root_set(word, aug_cnf)
            local ok = root ~= nil and root[product_var(lhs_img)] == true
            verify_cache[key] = ok
            return ok
        end

        -- DFS over variable images; f forced on the start symbol.
        -- Most-constrained-first ordering keeps the product-mode
        -- branching (candidates grow quadratically in |V|) feasible
        local order = {}
        for _, var in ipairs(sub_vars_list) do
            if var ~= sub_kernel.start then
                order[#order + 1] = var
            end
        end
        table.sort(order, function(a, b)
            local ca, cb = #candidates(a), #candidates(b)
            if ca ~= cb then return ca < cb end
            return a < b
        end)
        local budget = {count = 0, max = max_product > 1 and 6000 or 20000}

        -- verify every rule whose rhs variables are all assigned;
        -- cheap because verifies() caches per (image, word)
        local function check_complete_rules()
            for _, rule in ipairs(sub_kernel.rules) do
                local complete = assign[rule.lhs] ~= nil
                if complete then
                    for _, sym in ipairs(rule.rhs) do
                        if sub_var_set[sym] and not assign[sym] then
                            complete = false
                            break
                        end
                    end
                end
                if complete and not verifies(assign[rule.lhs], rule.rhs) then
                    return false
                end
            end
            return true
        end

        local function dfs(i)
            budget.count = budget.count + 1
            if budget.count > budget.max then
                return nil
            end
            if i > #order then
                return check_complete_rules()
            end
            local var = order[i]
            for _, img in ipairs(candidates(var)) do
                assign[var] = img
                if check_complete_rules() then
                    local res = dfs(i + 1)
                    if res ~= false then
                        return res
                    end
                end
                assign[var] = nil
            end
            return false
        end
        local result = dfs(1)
        return result == true
    end

    -- When every strongly connected component of the variable
    -- dependency graph is either acyclic or linear in one direction
    -- (the component's variable occurs only at one end of each
    -- right-hand side), every variable language is regular and the
    -- whole language can be compiled to an NFA: acyclic variables and
    -- linear components become NFA fragments in topological order,
    -- references to already compiled variables splice in their
    -- fragments. compare_dfa then decides equality exactly. Returns
    -- nil when some component is neither acyclic nor uniformly linear
    -- (the language may still be regular, but this construction cannot
    -- show it).
    local function grammar_to_regular_nfa(grammar)
        local base = normalized_rules(grammar)
        if not base then
            return nil
        end
        local rules = base.rules

        -- variables are the lhs symbols (rhs occurrences are
        -- productive after pruning, hence also lhs somewhere)
        local is_var = {}
        for _, rule in ipairs(rules) do
            is_var[rule.lhs] = true
        end

        -- SCCs of the variable dependency graph (Tarjan, iterative
        -- enough for these sizes: simple recursive would do, but keep
        -- it explicit-free via the standard recursive variant on a
        -- small graph)
        local index, lowlink, on_stack, stack = {}, {}, {}, {}
        local idx_counter = 0
        local sccs = {}
        local deps = {}
        for _, rule in ipairs(rules) do
            deps[rule.lhs] = deps[rule.lhs] or {}
            for _, sym in ipairs(rule.rhs) do
                if is_var[sym] then
                    deps[rule.lhs][sym] = true
                end
            end
        end
        -- variables that appear on no lhs but on some rhs are
        -- impossible after pruning; add lhs-only vars already covered
        local function strongconnect(v)
            index[v] = idx_counter
            lowlink[v] = idx_counter
            idx_counter = idx_counter + 1
            stack[#stack + 1] = v
            on_stack[v] = true
            for w,_ in pairs(deps[v] or {}) do
                if not index[w] then
                    strongconnect(w)
                    lowlink[v] = math.min(lowlink[v], lowlink[w])
                elseif on_stack[w] then
                    lowlink[v] = math.min(lowlink[v], index[w])
                end
            end
            if lowlink[v] == index[v] then
                local scc = {}
                while true do
                    local w = stack[#stack]
                    stack[#stack] = nil
                    on_stack[w] = nil
                    scc[#scc + 1] = w
                    if w == v then break end
                end
                sccs[#sccs + 1] = scc
            end
        end
        for _, rule in ipairs(rules) do
            if not index[rule.lhs] then
                strongconnect(rule.lhs)
            end
        end
        if not is_var[base.start] then
            -- start has no rules: language is empty -> empty NFA
            local nfa = automata.make_nfa(true)
            nfa:add_state("q0")
            nfa:set_initial("q0", true)
            return nfa
        end

        -- scc id per variable
        local scc_of = {}
        for i, scc in ipairs(sccs) do
            for _, v in ipairs(scc) do
                scc_of[v] = i
            end
        end

        -- direction of a cyclic component: "left"/"right"/nil(nonlinear)
        local scc_dir = {}
        for i, scc in ipairs(sccs) do
            local cyclic = #scc > 1
            if not cyclic then
                local v = scc[1]
                cyclic = deps[v] and deps[v][v] or false
            end
            if cyclic then
                local direction, ok = nil, true
                for _, v in ipairs(scc) do
                    for _, rule in ipairs(rules) do
                        if rule.lhs == v then
                            local scc_pos = {}
                            for pos, sym in ipairs(rule.rhs) do
                                if is_var[sym] and scc_of[sym] == i then
                                    scc_pos[#scc_pos + 1] = pos
                                end
                            end
                            if #scc_pos > 1 then
                                ok = false
                            elseif #scc_pos == 1 then
                                local p = scc_pos[1]
                                if p ~= 1 or p ~= #rule.rhs then
                                    local dir = (p == 1) and "left" or
                                        (p == #rule.rhs) and "right" or nil
                                    if not dir or
                                        (direction and direction ~= dir) then
                                        ok = false
                                    else
                                        direction = dir
                                    end
                                end
                            end
                        end
                        if not ok then break end
                    end
                    if not ok then break end
                end
                if not ok then
                    return nil
                end
                scc_dir[i] = direction or "left"
            end
        end

        -- NFA assembly. Embedding a variable X means building a fresh,
        -- private fragment: sharing a fragment between call sites is
        -- unsound, because a path could enter through one site and
        -- leave through another site's continuation. The per-call
        -- (entry, exit) pair accepts exactly L(X). Inside one linear
        -- component, variable states are shared -- that part is the
        -- standard linear-grammar construction. A state cap keeps the
        -- (in the worst case exponential) unfolding bounded; exceeding
        -- it just means "unsupported", never a wrong answer.
        local nfa = automata.make_nfa(true)
        local chain_counter = 0
        local max_states = 2000
        local state_count = 0
        local function fresh(prefix)
            chain_counter = chain_counter + 1
            state_count = state_count + 1
            if state_count > max_states then
                return nil
            end
            local name = prefix .. "\0" .. chain_counter
            nfa:add_state(name)
            return name
        end

        -- emit a path spelling out `items` from `from` to `to`;
        -- build_var provides fresh fragments for variable items
        local build_var
        local function emit_items(from, items, to)
            local current = from
            for pos, sym in ipairs(items) do
                local nxt = (pos == #items) and to or fresh("qc")
                if not nxt then return nil end
                if is_var[sym] then
                    local e, x = build_var(sym)
                    if not e then return nil end
                    nfa:add_transition(current, "", e)
                    nfa:add_transition(x, "", nxt)
                else
                    nfa:add_transition(current, sym, nxt)
                end
                current = nxt
            end
            if #items == 0 then
                nfa:add_transition(from, "", to)
            end
            return true
        end

        -- returns fresh (entry, exit) states accepting exactly L(var),
        -- or nil when the construction is unsupported/too big
        build_var = function(var)
            local i = scc_of[var]
            if not i then
                return nil
            end
            if not scc_dir[i] then
                -- acyclic variable: fresh entry, fresh exit, one path
                -- per rule
                local e, x = fresh("i"), fresh("v")
                if not e or not x then return nil end
                for _, rule in ipairs(rules) do
                    if rule.lhs == var then
                        if not emit_items(e, rule.rhs, x) then
                            return nil
                        end
                    end
                end
                return e, x
            elseif scc_dir[i] == "left" then
                -- shared init, per-var end states; X -> Y T becomes
                -- state(Y) --T--> state(X), X -> T init --T--> state(X)
                local init = fresh("i")
                if not init then return nil end
                local vstate = {}
                for _, v in ipairs(sccs[i]) do
                    vstate[v] = fresh("v")
                    if not vstate[v] then return nil end
                end
                for _, v in ipairs(sccs[i]) do
                    for _, rule in ipairs(rules) do
                        if rule.lhs == v then
                            local rhs = {}
                            for k, sym in ipairs(rule.rhs) do
                                rhs[k] = sym
                            end
                            local from
                            if #rhs > 0 and is_var[rhs[1]]
                                and scc_of[rhs[1]] == i then
                                from = vstate[table.remove(rhs, 1)]
                            else
                                from = init
                            end
                            if not emit_items(from, rhs, vstate[v]) then
                                return nil
                            end
                        end
                    end
                end
                return init, vstate[var]
            else
                -- right-linear: per-var start states, shared fin;
                -- X -> T Y becomes state(X) --T--> state(Y), X -> T
                -- becomes state(X) --T--> fin
                local fin = fresh("f")
                if not fin then return nil end
                local vstate = {}
                for _, v in ipairs(sccs[i]) do
                    vstate[v] = fresh("v")
                    if not vstate[v] then return nil end
                end
                for _, v in ipairs(sccs[i]) do
                    for _, rule in ipairs(rules) do
                        if rule.lhs == v then
                            local rhs = {}
                            for k, sym in ipairs(rule.rhs) do
                                rhs[k] = sym
                            end
                            local to
                            if #rhs > 0 and is_var[rhs[#rhs]]
                                and scc_of[rhs[#rhs]] == i then
                                to = vstate[rhs[#rhs]]
                                rhs[#rhs] = nil
                            else
                                to = fin
                            end
                            if not emit_items(vstate[v], rhs, to) then
                                return nil
                            end
                        end
                    end
                end
                return vstate[var], fin
            end
        end

        local e, x = build_var(base.start)
        if not e then
            return nil
        end
        nfa:set_initial(e, true)
        nfa:set_accepting(x, true)
        return nfa
    end

    -- exposed for tests/debugging
    automata._debug_regular_nfa = grammar_to_regular_nfa
    automata._debug_normalized_rules = normalized_rules

    -- exact comparison when both grammars compile to an NFA through
    -- the regularity construction above; nil when either does not
    function automata.grammar_compare_regular(grammar1, grammar2)
        local nfa1 = grammar_to_regular_nfa(grammar1)
        local nfa2 = nfa1 and grammar_to_regular_nfa(grammar2)
        if not nfa1 or not nfa2 then
            return nil
        end
        -- bounded determinisation: nil means out of budget, not
        -- a verdict
        local ok1, d1 = pcall(automata.nfa_to_dfa, nfa1, 4000)
        local ok2, d2 = pcall(automata.nfa_to_dfa, nfa2, 4000)
        if not (ok1 and d1) or not (ok2 and d2) then
            return nil
        end
        return automata.compare_dfa(d1, d2)
    end

    -- equality by mutual rule simulation on the simplified rule lists:
    -- sound because a simulating map transfers derivations. Also tried
    -- on the CNF kernels, whose uniform shape sometimes exposes a
    -- simulation the original decomposition hides. When no
    -- variable-to-variable map is found, the search is widened to
    -- products of up to PRODUCT_LEN variables, which can express that
    -- one variable's language is embedded in a concatenation of
    -- others
    local PRODUCT_LEN = 3
    function automata.grammar_simulated_equal(grammar1, grammar2)
        local k1 = normalized_rules(grammar1)
        local k2 = normalized_rules(grammar2)
        if not k1 or not k2 then
            return nil
        end
        local fwd = grammar_simulates(k1, k2)
        local bwd = grammar_simulates(k2, k1)
        if not (fwd and bwd) then
            local c1 = normalized_rule_kernel(grammar1)
            local c2 = normalized_rule_kernel(grammar2)
            fwd = grammar_simulates(c1, c2)
            bwd = grammar_simulates(c2, c1)
        end
        if not (fwd and bwd) then
            if not fwd then
                fwd = grammar_simulates(k1, k2, PRODUCT_LEN)
            end
            if not bwd then
                bwd = grammar_simulates(k2, k1, PRODUCT_LEN)
            end
        end
        if not (fwd and bwd) then
            local c1 = normalized_rule_kernel(grammar1)
            local c2 = normalized_rule_kernel(grammar2)
            if not fwd then
                fwd = grammar_simulates(c1, c2, PRODUCT_LEN)
            end
            if not bwd then
                bwd = grammar_simulates(c2, c1, PRODUCT_LEN)
            end
        end
        if fwd and bwd then
            return true
        end
        return false
    end

    -- Sentential-form reachability: can `from_form` rewrite to
    -- `to_form`?  For noncontracting grammars forms never shrink, so
    -- the search space is bounded by |to_form| and `false` is exact;
    -- for contracting ones the search is capped and `nil` reports
    -- "not verified" instead of "unreachable".  Soundness only ever
    -- needs the `true` answers.
    local function grammar_form_reachable(grammar, from_form, to_form,
                                          options)
        options = options or {}
        local max_explored = options.max_explored or 2000
        local noncontracting =
            automata.grammar_is_noncontracting(grammar)
        local max_len = noncontracting and to_form:len()
            or (to_form:len() + (options.form_slack or 2))
        if from_form:len() > max_len then
            return nil
        end
        local target = tostring(to_form)
        if tostring(from_form) == target then
            return true
        end
        -- the invariant value is preserved along *any* derivation
        -- chain, so the reference here is the value of from_form --
        -- NOT the start value: from_form is typically not reachable
        -- from the start at all (rule images in csg_simulates).  A
        -- successor outside the bound (nil value) is kept: contracting
        -- rules may later remove separators and still reach the target
        local invs = options.invariants ~= false
            and invariants_of(grammar, options) or nil
        local base = nil
        if invs then
            base = {}
            for i, inv in ipairs(invs) do
                base[i] = invariant_value(inv, from_form)
            end
        end
        local seen = {[tostring(from_form)] = true}
        local todo = {from_form}
        local head = 1
        local explored = 0
        while head <= #todo and not deadline_expired(options) do
            local form = todo[head]
            head = head + 1
            explored = explored + 1
            if explored > max_explored then
                return nil
            end
            for _, succ in ipairs(
                grammar_word_successors_list(form, grammar)) do
                if succ:len() <= max_len then
                    local s = tostring(succ)
                    if not seen[s] then
                        if s == target then
                            return true
                        end
                        seen[s] = true
                        local pruned = false
                        if invs then
                            for i, inv in ipairs(invs) do
                                local b = base[i]
                                local v = invariant_value(inv, succ)
                                if b ~= nil and v ~= nil and v ~= b then
                                    pruned = true
                                    break
                                end
                            end
                        end
                        if not pruned then
                            todo[#todo + 1] = succ
                        end
                    end
                end
            end
        end
        -- false only after the frontier ran dry inside the deadline:
        -- an expired clock means "not decided", not "unreachable"
        if deadline_expired(options) then
            return nil
        end
        return false
    end

    -- Inclusion proof for arbitrary (also non-context-free) grammars
    -- by per-rule simulation: a map f from sub variables to sup
    -- symbols (terminals stay literal) transfers every derivation of
    -- sub if for EVERY sub rule lhs->rhs the image f(lhs) derives
    -- f(rhs) in sup -- the sub rule's effect is replayable inside any
    -- context, so whole sentential forms lift: f(S1) =>* f(w) = w.
    -- Mutual simulation then proves equality.  The per-rule check is
    -- bounded by grammar_form_reachable; unverifiable or over-budget
    -- candidates are rejected, so a found map is a real proof.
    local function csg_simulates(sub, sup, options)
        options = options or {}
        local max_nodes = options.max_nodes or 2000
        -- a variable may be embedded as a product of sup symbols
        -- (max_product = 1 keeps the classic symbol-to-symbol map);
        -- products catch congruences like X == "A#" that no
        -- single-symbol map expresses
        local max_product = options.max_product or 1
        local sub_varset = sub:get_variables()
        -- rules as plain symbol arrays
        local rules = {}
        for rule,_ in pairs(sub:get_rules()) do
            local lhs, rhs = {}, {}
            for i = 1, rule.lhs:len() do
                lhs[i] = rule.lhs:get_char(i)
            end
            for i = 1, rule.rhs:len() do
                rhs[i] = rule.rhs:get_char(i)
            end
            rules[#rules + 1] = {lhs = lhs, rhs = rhs}
        end
        -- candidate images: products over sup variables and terminals,
        -- shortest first
        local sup_varset = sup:get_variables()
        local sup_syms = {}
        for var,_ in pairs(sup_varset) do
            sup_syms[#sup_syms + 1] = var
        end
        local sup_terms = {}
        for sym,_ in pairs(sup:get_symbols()) do
            if not sup_varset[sym] then
                sup_terms[#sup_terms + 1] = sym
            end
        end
        table.sort(sup_syms)
        table.sort(sup_terms)
        for _, t in ipairs(sup_terms) do
            sup_syms[#sup_syms + 1] = t
        end
        local cands = {}
        local function gen_cands(acc, depth)
            if depth >= 1 then
                local c = {}
                for i, s in ipairs(acc) do c[i] = s end
                cands[#cands + 1] = c
            end
            if depth < max_product then
                for _, s in ipairs(sup_syms) do
                    acc[#acc + 1] = s
                    gen_cands(acc, depth + 1)
                    acc[#acc] = nil
                end
            end
        end
        gen_cands({}, 0)
        -- the empty product maps a variable to the empty word; the
        -- per-rule check then forces images to derive one another
        cands[#cands + 1] = {}
        local assign = {[sub:get_start_variable()] =
                        {sup:get_start_variable()}}
        local function mapped(seq)
            local out = automata.make_token_sequence()
            for _, s in ipairs(seq) do
                local m = assign[s]
                if m == nil then
                    if sub_varset[s] then
                        return nil  -- variable not yet assigned
                    end
                    out:insert_right_modify(s)  -- terminals stay literal
                else
                    for _, ms in ipairs(m) do
                        out:insert_right_modify(ms)
                    end
                end
            end
            return out
        end
        local verify_cache = {}
        local function rule_verified(r)
            local fl, fr = mapped(r.lhs), mapped(r.rhs)
            if not (fl and fr) then
                return true  -- not ready, check later when complete
            end
            local key = tostring(fl) .. "\1" .. tostring(fr)
            local res = verify_cache[key]
            if res == nil then
                res = grammar_form_reachable(sup, fl, fr, options)
                verify_cache[key] = res
            end
            return res == true
        end
        local function check_ready_rules()
            for _, r in ipairs(rules) do
                if not rule_verified(r) then
                    return false
                end
            end
            return true
        end
        -- order variables by lhs occurrence count (most constrained
        -- first), start symbol already fixed
        local occ = {}
        for _, r in ipairs(rules) do
            for _, s in ipairs(r.lhs) do
                if sub_varset[s] then
                    occ[s] = (occ[s] or 0) + 1
                end
            end
        end
        local order = {}
        for var,_ in pairs(sub_varset) do
            if var ~= sub:get_start_variable() then
                order[#order + 1] = var
            end
        end
        table.sort(order, function(a, b)
            local oa, ob = occ[a] or 0, occ[b] or 0
            if oa ~= ob then
                return oa > ob
            end
            return a < b
        end)
        local nodes = 0
        local function dfs(i)
            nodes = nodes + 1
            if nodes > max_nodes or deadline_expired(options) then
                return nil
            end
            if i > #order then
                return check_ready_rules()
            end
            local var = order[i]
            for _, cand in ipairs(cands) do
                assign[var] = cand
                if check_ready_rules() then
                    local res = dfs(i + 1)
                    if res ~= false then
                        return res
                    end
                end
                assign[var] = nil
            end
            return false
        end
        -- keep the tri-state: true = a verified map exists, false =
        -- the assignment space ran dry (no map within these bounds),
        -- nil = node/deadline cap hit mid-search (undecided).  Every
        -- caller treats non-true as "not proven", so the extra
        -- information is free
        return dfs(1)
    end
    automata._debug_csg_simulates = csg_simulates

    -- proven inclusion directions by per-rule simulation: inc12
    -- means L(grammar1) ⊆ L(grammar2) -- every derivation of
    -- grammar1 lifts along the found symbol map.  A direction that
    -- fails stays nil ("not proven", never "disproven").  The second
    -- direction is only probed when the first holds or becomes
    -- provable -- equality is impossible otherwise, and the
    -- deeper pass below must not spend the deadline on a direction
    -- whose counterpart already failed
    local function csg_simulate_directions(grammar1, grammar2, options)
        options = options or {}
        local inc12 = csg_simulates(grammar1, grammar2, options) or nil
        local inc21 = inc12
            and (csg_simulates(grammar2, grammar1, options) or nil)
        if inc12 and inc21 then
            return inc12, inc21
        end
        -- deeper congruences: a variable may stand for a product of
        -- two symbols (e.g. X == "A#").  Only for non-context-free
        -- pairs -- context-free ones are served better by the earlier
        -- structural stages and by enumeration, so the larger search
        -- space would just burn their budget.  The pass also gets at
        -- most half of the remaining deadline: the enumeration stage
        -- behind this one is the only producer of inequality
        -- witnesses and must keep a share
        if not options.max_product
            and not (automata.grammar_is_context_free(grammar1)
                and automata.grammar_is_context_free(grammar2))
            and not deadline_expired(options) then
            local deeper = {}
            for k, v in pairs(options) do
                deeper[k] = v
            end
            deeper.max_product = 2
            deeper.max_nodes = options.max_product_nodes or 4000
            if options.deadline then
                deeper.deadline = os.clock()
                    + (options.deadline - os.clock()) / 2
            end
            if not inc12 then
                inc12 = csg_simulates(grammar1, grammar2, deeper) or nil
            end
            if inc12 and not inc21 then
                inc21 = csg_simulates(grammar2, grammar1, deeper) or nil
            end
        end
        return inc12, inc21
    end

    -- mutual rule simulation proves language equality; also works on
    -- non-context-free grammars, where the structural provers cannot
    -- be used.  nil means "not proven", never "different"
    function automata.grammar_csg_simulated_equal(grammar1, grammar2,
                                                  options)
        options = options or {}
        local inc12, inc21 = csg_simulate_directions(
            grammar1, grammar2, options)
        if inc12 and inc21 then
            return true
        end
        return nil
    end

    -- Equality by Brzozowski-style derivative bisimulation: states
    -- are finite sets of symbol products over each grammar; a pair
    -- (P1, P2) stands for the residual languages of the two grammars
    -- after some common prefix. If nullability agrees on every
    -- reachable pair and the relation is closed under all terminal
    -- derivatives, the start languages are equal (coinduction --
    -- sound for arbitrary context-free grammars). Nullability
    -- mismatches yield proven differences: exploring the closure to
    -- completion upgrades a single witness to "<"/">" when no
    -- reverse-direction mismatch exists. The derivative space is
    -- generally infinite for non-regular languages, so state and
    -- product-length caps bound it; exceeding any cap or hitting a
    -- derivative cycle returns nil (undecided, never a guess).
    -- Returns "=", "<", ">", "!=" or nil, plus witness words.
    function automata.grammar_derivative_equal(grammar1, grammar2, options)
        options = options or {}
        local max_states = options.max_states or 4000
        local max_prod_len = options.max_prod_len or 64
        local max_expand = options.max_expand or 400
        local kernels = {}
        local sides = {}
        for idx, grammar in ipairs({grammar1, grammar2}) do
            local k = normalized_rules(grammar)
            if not k then
                return nil
            end
            kernels[idx] = k
            local vars = {[k.start] = true}
            local rules_by = {}
            local terminals = {}
            for _, rule in ipairs(k.rules) do
                vars[rule.lhs] = true
                rules_by[rule.lhs] = rules_by[rule.lhs] or {}
                rules_by[rule.lhs][#rules_by[rule.lhs] + 1] = rule.rhs
            end
            for _, rule in ipairs(k.rules) do
                for _, sym in ipairs(rule.rhs) do
                    if not vars[sym] then
                        terminals[sym] = true
                    end
                end
            end
            sides[idx] = {
                vars = vars,
                rules_by = rules_by,
                terminals = terminals,
                nullable = nullable_vars(k.rules),
            }
        end
        -- empty-language edge cases are decided by nullability alone
        local n1 = sides[1].nullable[kernels[1].start]
        local n2 = sides[2].nullable[kernels[2].start]
        if #kernels[1].rules == 0 and #kernels[2].rules == 0 then
            return "="
        end

        -- derivative of one product wrt a terminal, by head
        -- expansion: a^{-1}(X.beta) = Union_{X->g} a^{-1}(g.beta)
        -- plus a^{-1}(beta) when X is nullable; terminals consume the
        -- derivative or kill it. seq lists are capped; a growth past
        -- max_prod_len (left-recursive derivatives expand forever)
        -- or a global expansion budget overrun sets overflow and
        -- aborts the whole method
        local overflow = false
        local work_left = options.max_work or 150000
        local function residuals(side, prod, a)
            local out = {}
            local work = {prod}
            local expand = 0
            while #work > 0 do
                local seq = table.remove(work)
                if #seq == 0 then
                    -- lambda has no a-derivative
                elseif #seq > max_prod_len then
                    overflow = true
                    return nil
                elseif not side.vars[seq[1]] then
                    if seq[1] == a then
                        local p = {}
                        for j = 2, #seq do p[#p + 1] = seq[j] end
                        out[#out + 1] = p
                    end
                else
                    local h = seq[1]
                    expand = expand + 1
                    work_left = work_left - 1
                    if expand > max_expand or work_left < 0 then
                        overflow = true
                        return nil
                    end
                    for _, rhs in ipairs(side.rules_by[h] or {}) do
                        local q = {}
                        for _, s in ipairs(rhs) do q[#q + 1] = s end
                        for j = 2, #seq do q[#q + 1] = seq[j] end
                        work[#work + 1] = q
                    end
                    if side.nullable[h] then
                        local q = {}
                        for j = 2, #seq do q[#q + 1] = seq[j] end
                        work[#work + 1] = q
                    end
                end
            end
            return out
        end

        local max_set = options.max_set or 400
        local function deriv_state(side, P, a)
            local seen, out, n = {}, {}, 0
            for _, prod in ipairs(P) do
                local rs = residuals(side, prod, a)
                if rs == nil then
                    return nil
                end
                for _, p in ipairs(rs) do
                    local pk = table.concat(p, "\0")
                    if not seen[pk] then
                        seen[pk] = p
                        n = n + 1
                        if n > max_set then
                            overflow = true
                            return nil
                        end
                    end
                end
            end
            for _, p in pairs(seen) do
                out[#out + 1] = p
            end
            table.sort(out, function(x, y)
                return table.concat(x, "\0") < table.concat(y, "\0")
            end)
            return out
        end

        local function null_state(side, P)
            for _, prod in ipairs(P) do
                local all_null = true
                for _, sym in ipairs(prod) do
                    if not (side.vars[sym] and side.nullable[sym]) then
                        all_null = false
                        break
                    end
                end
                if all_null then
                    return true
                end
            end
            return false
        end

        local function state_key(P)
            local parts = {}
            for i, p in ipairs(P) do
                parts[i] = table.concat(p, "\0")
            end
            return table.concat(parts, "\1")
        end

        -- alphabet: union of both terminal sets
        local alphabet = {}
        for t,_ in pairs(sides[1].terminals) do alphabet[t] = true end
        for t,_ in pairs(sides[2].terminals) do alphabet[t] = true end
        local letters = {}
        for t,_ in pairs(alphabet) do letters[#letters + 1] = t end
        table.sort(letters)

        -- BFS over derivative pairs; parent[] reconstructs the word
        local start_pair = {{{kernels[1].start}}, {{kernels[2].start}}}
        local visited = {[state_key(start_pair[1]) .. "\2" ..
                          state_key(start_pair[2])] = true}
        local queue = {start_pair}
        local parent = {}
        local witness = {}  -- witness[1] = word in L1\L2, [2] = L2\L1
        local qi = 1
        while qi <= #queue do
            if #queue > max_states then
                if witness[1] and witness[2] then
                    return "!=", witness[1], witness[2]
                end
                return nil
            end
            local P1, P2 = queue[qi][1], queue[qi][2]
            local nul1, nul2 = null_state(sides[1], P1),
                               null_state(sides[2], P2)
            if nul1 ~= nul2 then
                -- rebuild the prefix that reached this pair
                local w, key = {}, state_key(P1) .. "\2" .. state_key(P2)
                while parent[key] do
                    w[#w + 1] = parent[key].char
                    key = parent[key].prev
                end
                local word = ""
                for i = #w, 1, -1 do word = word .. w[i] end
                local side_idx = nul1 and 1 or 2
                if not witness[side_idx] then
                    witness[side_idx] = word
                end
            end
            for _, a in ipairs(letters) do
                local D1 = deriv_state(sides[1], P1, a)
                local D2 = D1 and deriv_state(sides[2], P2, a)
                if D1 == nil or D2 == nil then
                    -- derivative space blew up: keep witnesses only
                    if witness[1] and witness[2] then
                        return "!=", witness[1], witness[2]
                    end
                    return nil
                end
                local key = state_key(D1) .. "\2" .. state_key(D2)
                if not visited[key] then
                    visited[key] = true
                    queue[#queue + 1] = {D1, D2}
                    parent[key] = {prev = state_key(P1) .. "\2" ..
                        state_key(P2), char = a}
                end
            end
            qi = qi + 1
        end
        if witness[1] and witness[2] then
            return "!=", witness[1], witness[2]
        elseif witness[1] then
            return ">", witness[1], nil
        elseif witness[2] then
            return "<", nil, witness[2]
        end
        return "="
    end

    -- Partial "equation solving": eliminate variables by substitution.
    -- Replacing every right-hand-side occurrence of a NON-recursive
    -- variable X by its rules (X -> g_i distributes into k rules per
    -- occurrence) preserves the language exactly. Iterating cheapest
    -- first shrinks both systems toward their recursive cores; the
    -- residual grammars then go through the normalisation/simulation
    -- provers again -- a different decomposition gives those another
    -- chance. Rule-count and round caps bound the substitution blowup.
    local function eliminate_acyclic(rules, start)
        rules = {table.unpack(rules)}
        local guard = 0
        while guard < 60 do
            guard = guard + 1
            -- dependency closure per variable (does X reach X?)
            local deps = {}
            local all_vars = {}
            for _, r in ipairs(rules) do
                all_vars[r.lhs] = true
            end
            local reaches = {}
            for v,_ in pairs(all_vars) do
                reaches[v] = {}
            end
            for _, r in ipairs(rules) do
                for _, s in ipairs(r.rhs) do
                    if all_vars[s] then
                        reaches[r.lhs][s] = true
                    end
                end
            end
            -- transitive closure (small)
            local changed = true
            while changed do
                changed = false
                for v,_ in pairs(all_vars) do
                    for w,_ in pairs(reaches[v]) do
                        for u,_ in pairs(reaches[w]) do
                            if not reaches[v][u] then
                                reaches[v][u] = true
                                changed = true
                            end
                        end
                    end
                end
            end
            -- rules per variable
            local rules_by = {}
            for _, r in ipairs(rules) do
                rules_by[r.lhs] = rules_by[r.lhs] or {}
                rules_by[r.lhs][#rules_by[r.lhs] + 1] = r
            end
            -- cheapest eliminable non-recursive non-start variable
            local best, best_cost = nil, math.huge
            for v,_ in pairs(all_vars) do
                if v ~= start and not reaches[v][v] then
                    local occ, prod = 0, #(rules_by[v] or {})
                    for _, r in ipairs(rules) do
                        for _, s in ipairs(r.rhs) do
                            if s == v then occ = occ + 1 end
                        end
                    end
                    if occ > 0 and prod > 0 then
                        local cost = occ * prod
                        if cost < best_cost then
                            best, best_cost = v, cost
                        end
                    end
                end
            end
            if not best then
                break
            end
            -- substitute best everywhere; remove its rules
            local new_rules = {}
            for _, r in ipairs(rules) do
                if r.lhs == best then
                    -- dropped
                else
                    local variants = {r.rhs}
                    local has_v = false
                    for _, s in ipairs(r.rhs) do
                        if s == best then has_v = true end
                    end
                    if has_v then
                        -- expand best at ALL occurrences: positions are
                        -- re-found on the current variant each round,
                        -- because a variable-length replacement shifts
                        -- every later occurrence
                        local changed_v = true
                        while changed_v do
                            changed_v = false
                            local nxt = {}
                            for _, base in ipairs(variants) do
                                local p = nil
                                for i, s in ipairs(base) do
                                    if s == best then p = i; break end
                                end
                                if p then
                                    changed_v = true
                                    for _, xr in ipairs(rules_by[best]) do
                                        local nv = {}
                                        for i, s in ipairs(base) do
                                            if i == p then
                                                for _, t in ipairs(xr.rhs) do
                                                    nv[#nv + 1] = t
                                                end
                                            else
                                                nv[#nv + 1] = s
                                            end
                                        end
                                        nxt[#nxt + 1] = nv
                                    end
                                else
                                    nxt[#nxt + 1] = base
                                end
                            end
                            variants = nxt
                            -- half-substituted rules would keep the
                            -- eliminated variable alive and change the
                            -- language, so bail out entirely instead
                            if #variants > 200 then
                                return nil
                            end
                        end
                    end
                    for _, v in ipairs(variants) do
                        new_rules[#new_rules + 1] = {lhs = r.lhs, rhs = v}
                    end
                    if #new_rules > 600 then
                        return nil
                    end
                end
            end
            rules = new_rules
        end
        return {rules = rules, start = start}
    end

    -- equality via equation solving: substitute away non-recursive
    -- variables in both grammars, then let the structural provers
    -- decide the residual cores
    function automata.grammar_solved_equal(grammar1, grammar2)
        local k1 = normalized_rules(grammar1)
        local k2 = normalized_rules(grammar2)
        if not k1 or not k2 then
            return nil
        end
        local e1 = eliminate_acyclic(k1.rules, k1.start)
        local e2 = eliminate_acyclic(k2.rules, k2.start)
        if not e1 or not e2 then
            return nil
        end
        local r1 = rules_to_grammar(e1.rules, e1.start)
        local r2 = rules_to_grammar(e2.rules, e2.start)
        if automata.grammar_normalized_equal(r1, r2) == true then
            return true
        end
        if automata.grammar_simulated_equal(r1, r2) == true then
            return true
        end
        return false
    end

    -- Equality by bounded stepwise transformation: BFS from both
    -- grammars through language-preserving rewrites, trying to reach
    -- alpha-equivalent presentations. Rewrites: unfold a variable
    -- occurrence into all of its rules (substitution), fold a product
    -- pattern that occurs twice into a fresh variable, and
    -- normalisation after each step. Both directions search
    -- simultaneously and a shared shape signature buckets candidates
    -- for the alpha-equivalence test. Depth and state caps bound the
    -- branching; exhausting the space means "not proven", never
    -- "unequal".
    local function transform_shape_sig(kernel)
        local vars = {}
        for _, r in ipairs(kernel.rules) do
            vars[r.lhs] = true
        end
        local parts = {}
        for i, r in ipairs(kernel.rules) do
            local rhs = {}
            for j, s in ipairs(r.rhs) do
                rhs[j] = vars[s] and "?" or ("#" .. s)
            end
            parts[i] = table.concat(rhs, ",")
        end
        table.sort(parts)
        return #kernel.rules .. "|" .. table.concat(parts, ";")
    end

    local function transform_kernel(kernel)
        return normalized_rules(rules_to_grammar(kernel.rules, kernel.start))
    end

    local function transforms(kernel)
        local out = {}
        local rules_by = {}
        local varset = {}
        for _, r in ipairs(kernel.rules) do
            rules_by[r.lhs] = rules_by[r.lhs] or {}
            rules_by[r.lhs][#rules_by[r.lhs] + 1] = r
            varset[r.lhs] = true
        end
        -- unfold each rhs variable occurrence
        for ri, r in ipairs(kernel.rules) do
            for i, s in ipairs(r.rhs) do
                if varset[s] then
                    local xrules = rules_by[s]
                    if #xrules <= 8 and
                        #kernel.rules - 1 + #xrules <= 80 then
                        local nk = {rules = {}, start = kernel.start}
                        for rj, rr in ipairs(kernel.rules) do
                            if rj ~= ri then
                                nk.rules[#nk.rules + 1] = rr
                            end
                        end
                        for _, xr in ipairs(xrules) do
                            local nr = {}
                            for j = 1, i - 1 do nr[#nr + 1] = r.rhs[j] end
                            for _, t in ipairs(xr.rhs) do nr[#nr + 1] = t end
                            for j = i + 1, #r.rhs do nr[#nr + 1] = r.rhs[j] end
                            nk.rules[#nk.rules + 1] = {lhs = r.lhs, rhs = nr}
                        end
                        out[#out + 1] = nk
                    end
                end
            end
        end
        -- fold every length-2 product pattern used at least twice
        local patterns = {}
        local pat_order = {}
        for _, r in ipairs(kernel.rules) do
            for i = 1, #r.rhs - 1 do
                local key = r.rhs[i] .. "\0" .. r.rhs[i + 1]
                if not patterns[key] then
                    patterns[key] = {count = 0, a = r.rhs[i], b = r.rhs[i + 1]}
                    pat_order[#pat_order + 1] = key
                end
                patterns[key].count = patterns[key].count + 1
            end
        end
        table.sort(pat_order)
        -- the fresh variable must not collide with any symbol already
        -- present in the kernel, not even one that only occurs on
        -- right-hand sides (it would be a terminal today)
        local used_names = {}
        for _, r in ipairs(kernel.rules) do
            used_names[r.lhs] = true
            for _, s in ipairs(r.rhs) do
                used_names[s] = true
            end
        end
        local fcounter = 0
        for _, key in ipairs(pat_order) do
            local pat = patterns[key]
            if pat.count >= 2 then
                fcounter = fcounter + 1
                local fname = "ZZ" .. fcounter
                while used_names[fname] do
                    fcounter = fcounter + 1
                    fname = "ZZ" .. fcounter
                end
                used_names[fname] = true
                local nk = {rules = {}, start = kernel.start}
                for _, r in ipairs(kernel.rules) do
                    local nr = {}
                    local j = 1
                    while j <= #r.rhs do
                        if j < #r.rhs and
                            r.rhs[j] == pat.a and r.rhs[j + 1] == pat.b then
                            nr[#nr + 1] = fname
                            j = j + 2
                        else
                            nr[#nr + 1] = r.rhs[j]
                            j = j + 1
                        end
                    end
                    nk.rules[#nk.rules + 1] = {lhs = r.lhs, rhs = nr}
                end
                nk.rules[#nk.rules + 1] = {lhs = fname, rhs = {pat.a, pat.b}}
                if #nk.rules <= 80 then
                    out[#out + 1] = nk
                end
            end
        end
        return out
    end

    function automata.grammar_transform_equal(grammar1, grammar2, options)
        options = options or {}
        local max_depth = options.max_depth or 2
        local max_states = options.max_states or 1200
        local k1 = normalized_rules(grammar1)
        local k2 = normalized_rules(grammar2)
        if not k1 or not k2 then
            return nil
        end
        -- bucket: shape signature -> list of {kernel, grammar}
        local buckets = {[1] = {}, [2] = {}}
        local frontiers = {[1] = {k1}, [2] = {k2}}
        local nstates = 0
        local function try_add(side, k)
            local sig = transform_shape_sig(k)
            local g = rules_to_grammar(k.rules, k.start)
            local other = 3 - side
            for _, cand in ipairs(buckets[other][sig] or {}) do
                if automata.grammars_alpha_equivalent(g, cand.grammar) == true then
                    return true
                end
            end
            local b = buckets[side][sig] or {}
            -- skip if an alpha-equivalent kernel is already stored
            for _, cand in ipairs(b) do
                if automata.grammars_alpha_equivalent(g, cand.grammar) == true then
                    return false
                end
            end
            b[#b + 1] = {kernel = k, grammar = g}
            buckets[side][sig] = b
            return false
        end
        -- depth 0: are the normalised kernels alpha-equivalent?
        if try_add(1, k1) or try_add(2, k2) then
            return true
        end
        nstates = 2
        for depth = 1, max_depth do
            for side = 1, 2 do
                local nxt = {}
                for _, k in ipairs(frontiers[side]) do
                    for _, nk in ipairs(transforms(k)) do
                        local ck = transform_kernel(nk)
                        if ck and nstates < max_states then
                            if try_add(side, ck) then
                                return true
                            end
                            nstates = nstates + 1
                            nxt[#nxt + 1] = ck
                        end
                    end
                end
                frontiers[side] = nxt
            end
        end
        return false
    end

    -- ==================================================================
    -- Equality via verified regular fixpoint certificates.
    --
    -- Viewing a grammar's rules as an operator Phi on vectors of
    -- languages (one component per variable), the generated languages
    -- are its least fixpoint. A certificate is a vector R of regular
    -- languages -- represented as DFAs -- satisfying Phi_X(R) = R_X for
    -- every variable X, verified by building an NFA for each
    -- right-hand-side union and comparing DFAs. Under two structural
    -- preconditions such a fixpoint is automatically the *least*
    -- fixpoint, hence R_X = L(X) exactly:
    --   * Phi(R) <= R makes R a prefixpoint, so lfp(Phi) <= R always.
    --   * For R <= Phi(R) to imply R <= L, every w in R_X must
    --     decompose through a rule into strictly shorter variable
    --     parts; strong induction on |w| then produces a derivation.
    --     Strictness is measured on (|w|, unit-rule depth): rules
    --     containing a terminal are always strict, bare-variable rules
    --     need an acyclic unit-rule graph, and in all-variable
    --     products no component may produce epsilon (checked on the
    --     grammar's nullability and again on each hypothesised DFA).
    -- Hypotheses are fitted from sampled words: each word decomposes
    -- into runs of equal letters; samples sharing a run skeleton
    -- contribute exponent observations per position, generalised to
    -- exact / lower-bounded / periodic exponent classes. Every check
    -- is automata-exact, so a bad guess only costs a nil, never a
    -- wrong verdict.

    local function gcd_int(a, b)
        while b > 0 do
            a, b = b, a % b
        end
        return a
    end

    -- run-length decomposition: "aabcc" -> {{"a",2},{"b",1},{"c",2}}
    local function word_runs(word)
        local runs = {}
        local i = 1
        while i <= #word do
            local j = i + 1
            while j <= #word and word:sub(j, j) == word:sub(i, i) do
                j = j + 1
            end
            runs[#runs + 1] = {letter = word:sub(i, i), n = j - i}
            i = j
        end
        return runs
    end

    -- candidate exponent classes for observed exponents; a class is
    -- {exact={n,...}} or {min=m} (all n >= m) or {min=m,mod=q,res=r}
    -- (all n >= m with n == r mod q)
    local function class_candidates(values)
        local vs = {}
        for n in pairs(values) do
            vs[#vs + 1] = n
        end
        table.sort(vs)
        if #vs == 1 then
            return {{exact = vs}}
        end
        local min = vs[1]
        local q = 0
        for i = 2, #vs do
            q = gcd_int(q, vs[i] - min)
        end
        local cands, seen = {}, {}
        local function add(c)
            local key
            if c.exact then
                key = "e" .. table.concat(c.exact, ",")
            else
                key = "m" .. c.min .. "q" .. (c.mod or 0) .. "r" ..
                    (c.res or 0)
            end
            if not seen[key] then
                seen[key] = true
                cands[#cands + 1] = c
            end
        end
        local function add_periodic()
            if q > 1 then
                add({min = min, mod = q, res = min % q})
                -- coarser periods: divisors of q (sparse samples can
                -- exaggerate the apparent period)
                for d = q - 1, 2, -1 do
                    if q % d == 0 then
                        add({min = min, mod = d, res = min % d})
                    end
                end
            end
            add({min = min})
        end
        -- a tight spread of small values is more likely a bounded set
        -- than the visible part of an unbounded tail
        if #vs <= 6 and vs[#vs] - min < 4 then
            add({exact = vs})
        end
        add_periodic()
        if #vs <= 6 then
            add({exact = vs})
        end
        return cands
    end

    -- append NFA fragment accepting c^class between states from/to
    local function emit_class(nfa, fresh, from, c, class, to)
        if class.exact then
            for _, n in ipairs(class.exact) do
                if n == 0 then
                    nfa:add_transition(from, "", to)
                else
                    local cur = from
                    for i = 1, n do
                        local nxt = (i == n) and to or fresh("x")
                        nfa:add_transition(cur, c, nxt)
                        cur = nxt
                    end
                end
            end
        elseif not class.mod or class.mod <= 1 then
            local cur = from
            for _ = 1, class.min do
                local nxt = fresh("m")
                nfa:add_transition(cur, c, nxt)
                cur = nxt
            end
            nfa:add_transition(cur, c, cur)
            nfa:add_transition(cur, "", to)
        else
            local q = class.mod
            local cur = from
            for _ = 1, class.min do
                local nxt = fresh("m")
                nfa:add_transition(cur, c, nxt)
                cur = nxt
            end
            -- cycle p_0 .. p_{q-1}: p_j means min+j copies consumed
            local p = {}
            for j = 0, q - 1 do
                p[j] = (j == 0) and cur or fresh("p")
            end
            for j = 0, q - 1 do
                nfa:add_transition(p[j], c, p[(j + 1) % q])
                if (class.min + j) % q == class.res % q then
                    nfa:add_transition(p[j], "", to)
                end
            end
        end
    end

    -- NFA for a hypothesis: a list of terms, each a list of factors
    -- {letter, class}; an empty term accepts only epsilon
    local function hypothesis_nfa(terms)
        local nfa = automata.make_nfa(true)
        local counter = 0
        local function fresh(prefix)
            counter = counter + 1
            local name = prefix .. "\0" .. counter
            nfa:add_state(name)
            return name
        end
        local q0, qf = fresh("h0"), fresh("hf")
        nfa:set_initial(q0, true)
        nfa:set_accepting(qf, true)
        for _, term in ipairs(terms) do
            local cur = fresh("te")
            nfa:add_transition(q0, "", cur)
            for _, f in ipairs(term) do
                local nxt = fresh("tn")
                emit_class(nfa, fresh, cur, f.letter, f.class, nxt)
                cur = nxt
            end
            nfa:add_transition(cur, "", qf)
        end
        return nfa
    end

    -- NFA accepting the union of R(rhs) over all rules lhs -> rhs,
    -- embedding a private copy of each variable's candidate DFA.
    -- Determinisation of such a product is exponential in the rule
    -- length; refuse when the estimate exceeds max_phi_states.
    local function phi_nfa(rules, varset, lhs, dfa_map, max_phi_states)
        local nfa = automata.make_nfa(true)
        local counter = 0
        local function fresh(prefix)
            counter = counter + 1
            local name = prefix .. "\0" .. counter
            nfa:add_state(name)
            return name
        end
        local q0, qf = fresh("p0"), fresh("pf")
        nfa:set_initial(q0, true)
        nfa:set_accepting(qf, true)
        for _, rule in ipairs(rules) do
            if rule.lhs == lhs then
                if #rule.rhs == 0 then
                    nfa:add_transition(q0, "", qf)
                else
                    local estimate = 2
                    for _, sym in ipairs(rule.rhs) do
                        if varset[sym] then
                            local d = dfa_map[sym]
                            if not d then
                                return nil
                            end
                            local n = 0
                            for _ in pairs(d:get_states()) do
                                n = n + 1
                            end
                            estimate = estimate * (n + 1)
                            if estimate > max_phi_states then
                                return nil
                            end
                        end
                    end
                    local cur = q0
                    for pos, sym in ipairs(rule.rhs) do
                        local nxt = (pos == #rule.rhs) and qf or fresh("pc")
                        if varset[sym] then
                            local d = dfa_map[sym]
                            if not d then
                                return nil
                            end
                            local map = {}
                            for st in pairs(d:get_states()) do
                                map[st] = fresh("d")
                            end
                            for _, t in ipairs(d:get_transitions()) do
                                nfa:add_transition(map[t.from], t.label,
                                    map[t.target])
                            end
                            nfa:add_transition(cur, "", map[d:get_initial()])
                            for st in pairs(d:get_states()) do
                                if d:is_accepting(st) then
                                    nfa:add_transition(map[st], "", nxt)
                                end
                            end
                        else
                            nfa:add_transition(cur, sym, nxt)
                        end
                        cur = nxt
                    end
                end
            end
        end
        return nfa
    end

    -- returns the DFA certifying L(start) exactly, or nil when no
    -- verified fixpoint certificate could be found
    local function certificate_dfa(grammar, options)
        options = options or {}
        local kernel = normalized_rules(grammar)
        if not kernel then
            return nil
        end
        local rules, start = kernel.rules, kernel.start
        local DEBUG = os.getenv("CERT_DEBUG")
        local varset = grammar:get_variables()
        local vars, var_order, allvar_rhs_vars = {}, {}, {}
        local unit_edges = {}
        for _, rule in ipairs(rules) do
            if not vars[rule.lhs] then
                vars[rule.lhs] = true
                var_order[#var_order + 1] = rule.lhs
            end
            local has_terminal = false
            for _, sym in ipairs(rule.rhs) do
                if varset[sym] then
                    if not vars[sym] then
                        vars[sym] = true
                        var_order[#var_order + 1] = sym
                    end
                else
                    has_terminal = true
                end
            end
            if #rule.rhs == 1 and varset[rule.rhs[1]] then
                unit_edges[rule.lhs] = unit_edges[rule.lhs] or {}
                unit_edges[rule.lhs][rule.rhs[1]] = true
            elseif #rule.rhs >= 2 and not has_terminal then
                -- in an all-variable product every part must be
                -- nonempty, or a sibling could carry the whole word
                for _, sym in ipairs(rule.rhs) do
                    allvar_rhs_vars[sym] = true
                end
            end
        end
        -- unit rules are sound only when acyclic: the induction measure
        -- is (word length, depth in the unit-rule DAG)
        local ucolor = {}
        local function uvisit(v)
            if ucolor[v] == 1 then
                return true  -- cycle
            end
            if ucolor[v] == 2 then
                return false
            end
            ucolor[v] = 1
            for w in pairs(unit_edges[v] or {}) do
                if uvisit(w) then
                    return true
                end
            end
            ucolor[v] = 2
            return false
        end
        for v in pairs(unit_edges) do
            if uvisit(v) then
                return nil
            end
        end
        -- a nullable variable in an all-variable right-hand side would
        -- break strictness; terminals make a part nonempty anyway
        local nullable = nullable_vars(rules)
        for v in pairs(allvar_rhs_vars) do
            if nullable[v] then
                return nil
            end
        end
        -- minimum terminal yield per variable, used to bound the
        -- breadth-first sampling below
        local min_yield = {}
        for v in pairs(vars) do
            min_yield[v] = math.huge
        end
        local ychanged = true
        while ychanged do
            ychanged = false
            for _, rule in ipairs(rules) do
                local y = 0
                for _, sym in ipairs(rule.rhs) do
                    if varset[sym] then
                        y = y + (min_yield[sym] or math.huge)
                    else
                        y = y + 1
                    end
                end
                if y < min_yield[rule.lhs] then
                    min_yield[rule.lhs] = y
                    ychanged = true
                end
            end
        end
        -- breadth-first derivation sampling: collect terminal words up
        -- to sample_len reachable from each variable. Leftmost
        -- expansion covers every word; min_yield bounds the frontier.
        local sample_len = options.sample_len or 16
        local max_forms = options.max_forms or 20000
        local prods = {}
        for _, rule in ipairs(rules) do
            prods[rule.lhs] = prods[rule.lhs] or {}
            local pl = prods[rule.lhs]
            pl[#pl + 1] = rule.rhs
        end
        local function sample_var(v)
            local words = {}
            local seen = {[v] = true}
            local frontier = {{v}}
            local forms = 1
            while #frontier > 0 and forms <= max_forms do
                local nxt = {}
                for _, form in ipairs(frontier) do
                    if forms + #nxt > max_forms then
                        break
                    end
                    local vi
                    for i, sym in ipairs(form) do
                        if varset[sym] then
                            vi = i
                            break
                        end
                    end
                    if vi then
                        for _, rhs in ipairs(prods[form[vi]] or {}) do
                            local nf = {}
                            local yield = 0
                            for i = 1, vi - 1 do
                                nf[#nf + 1] = form[i]
                                yield = yield + 1
                            end
                            for _, sym in ipairs(rhs) do
                                nf[#nf + 1] = sym
                                yield = yield + (varset[sym] and
                                    min_yield[sym] or 1)
                            end
                            for i = vi + 1, #form do
                                nf[#nf + 1] = form[i]
                                local sym = form[i]
                                yield = yield + (varset[sym] and
                                    min_yield[sym] or 1)
                            end
                            local key = table.concat(nf, "\x1f")
                            if yield <= sample_len and not seen[key] then
                                seen[key] = true
                                nxt[#nxt + 1] = nf
                            end
                        end
                    else
                        words[table.concat(form)] = true
                    end
                end
                forms = forms + #nxt
                frontier = nxt
            end
            return words
        end
        local samples = {}
        local t_sam = os.clock()
        for _, v in ipairs(var_order) do
            samples[v] = sample_var(v)
        end
        if DEBUG then
            io.stderr:write(string.format(
                "cert: sampling %.2fs\n", os.clock() - t_sam))
        end
        -- hypothesis candidate lists per variable
        local cand_terms = {}
        for _, v in ipairs(var_order) do
            local groups, gorder = {}, {}
            for w in pairs(samples[v]) do
                local runs = word_runs(w)
                local sk = {}
                for _, r in ipairs(runs) do
                    sk[#sk + 1] = r.letter
                end
                local key = table.concat(sk, "\x1f")
                local g = groups[key]
                if not g then
                    g = {letters = sk, exps = {}, npos = #runs,
                         count = 0}
                    groups[key] = g
                    gorder[#gorder + 1] = key
                end
                g.count = g.count + 1
                for pos, r in ipairs(runs) do
                    local e = g.exps[pos] or {}
                    e[r.n] = true
                    g.exps[pos] = e
                end
            end
            -- most-witnessed skeletons first; too many groups make the
            -- union hypothesis NFA explode under determinisation
            table.sort(gorder, function(x, y)
                if groups[x].count ~= groups[y].count then
                    return groups[x].count > groups[y].count
                end
                return x < y
            end)
            local max_groups = options.max_groups or 12
            while #gorder > max_groups do
                gorder[#gorder] = nil
            end
            if DEBUG then
                local ws = {}
                for w in pairs(samples[v]) do ws[#ws + 1] = w end
                table.sort(ws)
                io.stderr:write("cert: " .. v .. " samples: " ..
                    table.concat(ws, ",") .. "\n")
            end
            local cls = {}
            for _, key in ipairs(gorder) do
                cls[key] = {}
                for pos = 1, groups[key].npos do
                    cls[key][pos] = class_candidates(groups[key].exps[pos])
                end
            end
            -- variants: all-first-choice, then single-position
            -- alternates; enough to recover from one misfit per group
            local variants = {}
            local function build(pick)
                local terms = {}
                for _, key in ipairs(gorder) do
                    local g = groups[key]
                    local term = {}
                    for pos = 1, g.npos do
                        local cs = cls[key][pos]
                        local i = math.min(pick(key, pos), #cs)
                        term[pos] = {letter = g.letters[pos], class = cs[i]}
                    end
                    terms[#terms + 1] = term
                end
                variants[#variants + 1] = terms
            end
            build(function() return 1 end)
            -- most permissive combination: last candidate everywhere
            build(function(k, p) return #cls[k][p] end)
            local added = 0
            for _, key in ipairs(gorder) do
                for pos = 1, groups[key].npos do
                    for alt = 2, #cls[key][pos] do
                        build(function(k, p)
                            if k == key and p == pos then
                                return alt
                            end
                            return 1
                        end)
                        added = added + 1
                        if added >= 22 then
                            break
                        end
                    end
                    if added >= 22 then break end
                end
                if added >= 22 then break end
            end
            if DEBUG then
                for vi, terms in ipairs(variants) do
                    local parts = {}
                    for _, term in ipairs(terms) do
                        local fs = {}
                        for _, f in ipairs(term) do
                            local c = f.class
                            fs[#fs + 1] = f.letter .. (c.exact and
                                ("^" .. table.concat(c.exact, "|"))
                                or ("^>=" .. c.min ..
                                    (c.mod and c.mod > 1 and
                                        "mod" .. c.mod .. "r" .. c.res
                                        or "")))
                        end
                        parts[#parts + 1] = table.concat(fs, ".")
                    end
                    io.stderr:write("cert: " .. v .. " cand" .. vi ..
                        ": " .. table.concat(parts, " + ") .. "\n")
                end
            end
            cand_terms[v] = variants
        end
        -- determinise and cache each candidate; hypotheses with too
        -- many states would make the product check explode
        local max_dfa_states = options.max_dfa_states or 200
        local max_phi_states = options.max_phi_states or 4000
        local cand_dfa_cache = {}
        local function cand_dfa(v, i)
            cand_dfa_cache[v] = cand_dfa_cache[v] or {}
            if cand_dfa_cache[v][i] == nil then
                local ok, d
                local hn = hypothesis_nfa(cand_terms[v][i])
                local hn_states = 0
                for _ in pairs(hn:get_states()) do
                    hn_states = hn_states + 1
                end
                if hn_states <= (options.max_hyp_nfa or 300) then
                    -- determinisation is capped internally; nil result
                    -- means the subset lattice outgrew the budget
                    ok, d = pcall(automata.nfa_to_dfa, hn,
                        max_dfa_states)
                    ok = ok and (d ~= nil)
                end
                -- a variable in an all-variable right-hand side must
                -- not accept epsilon under the hypothesis
                if ok and d:is_accepting(d:get_initial())
                    and allvar_rhs_vars[v] then
                    ok = false
                end
                cand_dfa_cache[v][i] = ok and d or false
            end
            return cand_dfa_cache[v][i] or nil
        end
        -- tentative assignment, then sweep-verify until stable
        local t_sweep = os.clock()
        local dfas = {}
        for _, v in ipairs(var_order) do
            dfas[v] = cand_dfa(v, 1)
        end
        local choice = {}
        for _, v in ipairs(var_order) do
            choice[v] = 1
        end
        local sweeps = 0
        while sweeps < 60 do
            sweeps = sweeps + 1
            local changed = false
            local all_ok = true
            for _, v in ipairs(var_order) do
                -- check the current candidate under current neighbours
                local ok = false
                local d = dfas[v]
                if d then
                    local pnfa = phi_nfa(rules, varset, v, dfas,
                        max_phi_states)
                    if pnfa then
                        -- determinisation is capped internally; nil
                        -- means the subset lattice outgrew the budget
                        local pok, pd = pcall(automata.nfa_to_dfa,
                            pnfa, max_phi_states)
                        pok = pok and (pd ~= nil)
                        if pok and automata.compare_dfa(pd, d) == "=" then
                            ok = true
                        elseif DEBUG then
                            local _, cx1, cx2 = automata.compare_dfa(pd, d)
                            io.stderr:write(string.format(
                                "cert: %s cand %d fails cex_phi=%s cex_R=%s\n",
                                v, choice[v], tostring(cx1), tostring(cx2)))
                        end
                    elseif DEBUG then
                        io.stderr:write(string.format(
                            "cert: %s phi build failed\n", v))
                    end
                elseif DEBUG then
                    io.stderr:write(string.format(
                        "cert: %s no candidate dfa\n", v))
                end
                if not ok then
                    all_ok = false
                    -- advance this variable's candidate
                    local found = false
                    while choice[v] < #cand_terms[v] do
                        choice[v] = choice[v] + 1
                        local nd = cand_dfa(v, choice[v])
                        if nd then
                            dfas[v] = nd
                            changed = true
                            found = true
                            break
                        end
                    end
                    if not found then
                        dfas[v] = cand_dfa(v, choice[v])
                    end
                end
            end
            if all_ok then
                return dfas[start]
            end
            if not changed then
                if DEBUG then
                    io.stderr:write(string.format(
                        "cert: sweep done %.2fs\n",
                        os.clock() - t_sweep))
                end
                return nil
            end
        end
        if DEBUG then
            io.stderr:write(string.format(
                "cert: sweep cap %.2fs\n", os.clock() - t_sweep))
        end
        return nil
    end

    -- exact comparison when both grammars admit a verified regular
    -- fixpoint certificate; nil otherwise
    function automata.grammar_compare_certified(grammar1, grammar2, options)
        local d1 = certificate_dfa(grammar1, options)
        local d2 = d1 and certificate_dfa(grammar2, options)
        if not d1 or not d2 then
            return nil
        end
        return automata.compare_dfa(d1, d2)
    end

    -- compare the languages of two grammars; returns "=", "<", ">",
    -- "!=" or nil (undecided) like compare_dfa, plus counterexample
    -- words for the strict/difference cases (cex1 in L1\L2, cex2 in
    -- L2\L1). Every returned relation is proven, nil means the methods
    -- could not decide within options {max_length, max_iter, max_words}.
    -- A rule whose left-hand side can never occur in a reachable
    -- sentential form is dead weight: stripping it cannot change the
    -- language.  For grammars that are non-context-free only because
    -- of such dead rules (a mistyped C -> D written as CC -> D, say)
    -- this recovers a CYK-safe grammar with the same language.
    -- Firing possibilities are approximated by a fixpoint over
    -- "reachable symbol" and "possibly adjacent symbol pair": the
    -- approximation errs on the side of keeping rules, so a rule is
    -- stripped only when some lhs symbol is unreachable or some
    -- adjacent lhs pair provably never occurs.
    local function strip_dead_noncf_rules(grammar)
        local function needs_context(rule)
            return rule.lhs:len() > 1
                or not grammar:has_variable(rule.lhs:get_char(1))
        end
        local any_context = false
        for rule,_ in pairs(grammar:get_rules()) do
            if needs_context(rule) then
                any_context = true
                break
            end
        end
        if not any_context then
            return grammar
        end

        local reach = {[grammar:get_start_variable()] = true}
        local adj = {}
        local function adj_key(x, y)
            return x .. "\1" .. y
        end
        local function pair_iter()
            -- snapshot: the boundary loop adds pairs while iterating
            local keys = {}
            for key in pairs(adj) do
                keys[#keys + 1] = key
            end
            local i = 0
            return function()
                i = i + 1
                local key = keys[i]
                if key ~= nil then
                    return key, adj[key]
                end
            end
        end
        local function rule_firable(rule)
            for i = 1, rule.lhs:len() do
                if not reach[rule.lhs:get_char(i)] then
                    return false
                end
            end
            for i = 1, rule.lhs:len() - 1 do
                if not adj[adj_key(rule.lhs:get_char(i),
                                   rule.lhs:get_char(i + 1))] then
                    return false
                end
            end
            return true
        end
        local changed = true
        while changed do
            changed = false
            for rule,_ in pairs(grammar:get_rules()) do
                if rule_firable(rule) then
                    local rhs = rule.rhs
                    local n = rhs:len()
                    for i = 1, n do
                        local s = rhs:get_char(i)
                        if not reach[s] then
                            reach[s] = true
                            changed = true
                        end
                    end
                    for i = 1, n - 1 do
                        local k = adj_key(rhs:get_char(i),
                                          rhs:get_char(i + 1))
                        if not adj[k] then
                            adj[k] = true
                            changed = true
                        end
                    end
                    -- boundary effects: the neighbours of the replaced
                    -- pattern become neighbours of the rhs ends; for
                    -- an empty rhs the two neighbours meet
                    local first = rule.lhs:get_char(1)
                    local last = rule.lhs:get_char(rule.lhs:len())
                    for key,_ in pair_iter() do
                        local x, y = key:match("^(.*)\1(.*)$")
                        if n > 0 then
                            if y == first then
                                local k = adj_key(x, rhs:get_char(1))
                                if not adj[k] then
                                    adj[k] = true
                                    changed = true
                                end
                            end
                            if x == last then
                                local k = adj_key(rhs:get_char(n), y)
                                if not adj[k] then
                                    adj[k] = true
                                    changed = true
                                end
                            end
                        elseif y == first then
                            for key2,_ in pair_iter() do
                                local u, v = key2:match("^(.*)\1(.*)$")
                                if u == last then
                                    local k = adj_key(x, v)
                                    if not adj[k] then
                                        adj[k] = true
                                        changed = true
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end

        -- keep exactly the rules that can ever fire: a rule whose lhs
        -- symbols or adjacency pattern cannot occur in a reachable
        -- sentential form is dead weight; dropping it preserves the
        -- language for arbitrary grammar types and lets
        -- alpha-equivalence and enumeration match the clean version
        local reduced = automata.make_grammar()
        reduced:set_start_variable(grammar:get_start_variable())
        for rule,_ in pairs(grammar:get_rules()) do
            if rule_firable(rule) then
                reduced:add_rule(rule.lhs, rule.rhs)
            end
        end
        return reduced
    end

    local function grammar_compare_languages_impl(grammar1, grammar2,
                                                  options)
        options = options or {}

        -- identical up to variable renaming?
        if automata.grammars_alpha_equivalent(grammar1, grammar2) == true then
            return "="
        end

        -- provably equal after applying only language-preserving
        -- normalisation steps (pruning, inlining, merging, CNF) to
        -- both context-free grammars?
        if automata.grammar_normalized_equal(grammar1, grammar2) == true then
            return "="
        end

        -- provably equal by mutual rule simulation: a map taking every
        -- rule of one grammar to a derivation in the other transfers
        -- all derivation trees, so both inclusions hold
        if automata.grammar_simulated_equal(grammar1, grammar2) == true then
            return "="
        end

        -- provably equal by equation solving: non-recursive variables
        -- are eliminated by substitution and the residual cores are
        -- re-compared
        if automata.grammar_solved_equal(grammar1, grammar2) == true then
            return "="
        end

        -- provably equal by bounded stepwise transformation: BFS
        -- through unfold/fold rewrites toward an alpha-equivalent
        -- presentation
        if automata.grammar_transform_equal(grammar1, grammar2) == true then
            return "="
        end

        -- grammars whose variable SCCs are all acyclic or uniformly
        -- linear compile to NFAs; the DFA comparison then decides the
        -- relation exactly (covers the purely linear case below and
        -- mixed acyclic/linear decompositions)
        local rel, w1, w2 = automata.grammar_compare_regular(grammar1, grammar2)
        if rel then
            return rel, w1, w2
        end

        -- verified regular fixpoint certificates: grammars with
        -- nonlinear recursion can still have regular variable
        -- languages; a verified certificate decides them exactly
        local crel, cw1, cw2 = automata.grammar_compare_certified(
            grammar1, grammar2, options)
        if crel then
            return crel, cw1, cw2
        end

        -- linear grammars: exact automaton comparison (capped
        -- determinisation; over budget falls through to the bounded
        -- stages rather than hanging)
        local lin1 = grammar_linear_form(grammar1)
        local lin2 = grammar_linear_form(grammar2)
        if lin1 and lin2 then
            local ok1, dfa1 = pcall(automata.nfa_to_dfa,
                automata.grammar_to_nfa(grammar1, lin1 == "left"), 4000)
            local ok2, dfa2 = pcall(automata.nfa_to_dfa,
                automata.grammar_to_nfa(grammar2, lin2 == "left"), 4000)
            if ok1 and ok2 and dfa1 and dfa2 then
                return automata.compare_dfa(dfa1, dfa2)
            end
        end

        -- derivative bisimulation: coinductive quotient check over
        -- residual languages; decides arbitrary context-free grammars
        -- whose derivative space stays finite, with witnesses
        local drel, dw1, dw2 = automata.grammar_derivative_equal(
            grammar1, grammar2)
        if drel then
            return drel, dw1, dw2
        end

        -- mutual rule simulation: the only structural prover that
        -- also applies to non-context-free grammars; per-rule
        -- derivability is bounded by form-reachability.  The two
        -- directions are kept: a proven inclusion plus a
        -- counterexample below yields a proven strict subset, and a
        -- proven inclusion makes the opposite witness search
        -- vacuous -- inc12 means no word of language1 can be missing
        -- from language2, so searching for one is provably futile
        local inc12, inc21 = csg_simulate_directions(
            grammar1, grammar2, options)
        if inc12 and inc21 then
            return "="
        end
        -- direction 2 was only probed when direction 1 held; when
        -- inc12 failed inc21 is untried, and the witness loop may
        -- still retry it once if the scans suggest an inclusion
        local inc21_tried = inc12 == true

        -- sides whose language is provably empty.  For context-free
        -- grammars the minimum-yield fixpoint is exact; for general
        -- grammars a symbol can only reach a terminal word if some
        -- rule eliminates it into eliminable symbols, so a start
        -- symbol failing that fixpoint proves emptiness (induction:
        -- every symbol on a terminal derivation is eliminable)
        local function is_provably_empty(grammar)
            if automata.grammar_is_context_free(grammar) then
                return minimum_terminal_yields(grammar)
                    [grammar:get_start_variable()] == math.huge
            end
            local eliminable = {}
            for sym,_ in pairs(grammar:get_symbols()) do
                if not grammar:has_variable(sym) then
                    eliminable[sym] = true
                end
            end
            local changed = true
            while changed do
                changed = false
                for rule,_ in pairs(grammar:get_rules()) do
                    local ok = true
                    for i = 1, rule.rhs:len() do
                        if not eliminable[rule.rhs:get_char(i)] then
                            ok = false
                            break
                        end
                    end
                    if ok then
                        for i = 1, rule.lhs:len() do
                            local sym = rule.lhs:get_char(i)
                            if not eliminable[sym] then
                                eliminable[sym] = true
                                changed = true
                            end
                        end
                    end
                end
            end
            return not eliminable[grammar:get_start_variable()]
        end
        local empty1, empty2 = is_provably_empty(grammar1), is_provably_empty(grammar2)
        if empty1 and empty2 then
            return "="
        end
        if empty1 or empty2 then
            -- the other side is nonempty (finite min yield) or unknown;
            -- grab a witness word from the nonempty/unknown side
            local full = empty1 and grammar2 or grammar1
            local witness = automata.grammar_contains_word(nil, full, options)
            if witness then
                if empty1 then
                    return "<", nil, tostring(witness)
                end
                return ">", tostring(witness)
            end
            -- generator capped: fall through to enumeration
        end

        -- bounded enumeration + verified symmetric difference;
        -- yield-first ordering so short witnesses reached through
        -- long mutual recursion are not starved by the breadth-first
        -- frontier explosion.  When a side's enumeration is complete
        -- up to the length bound, a missing word is provably absent
        -- from that language (no separate membership check needed);
        -- and while *both* sides stay complete the bound is raised --
        -- each level only extends the witness reach, never the
        -- soundness argument
        local max_length = options.max_length or 10
        local ceiling = options.max_enum_length or options.max_length
            or 16
        -- when an enumeration comes back incomplete it capped on the
        -- number of explored forms, not on length: retrying with a
        -- bigger form budget reaches derivations that sit deeper in
        -- the breadth-first order.  Escalate that budget per round
        -- (the deadline still bounds the real work), and escalate the
        -- length bound once both sides finished exactly.
        local enum_words = options.max_words or 200000
        local enum_words_ceiling = options.max_enum_words
            or 16 * enum_words
        -- same memory bound the enumerators honour; checked between
        -- rounds so an escalating form budget cannot push the process
        -- over the edge one enumeration at a time
        local cex1, cex2
        -- deterministic order: shortest candidates first
        local function sorted_keys(t)
            local keys = {}
            for w,_ in pairs(t) do
                keys[#keys + 1] = w
            end
            table.sort(keys, function(a, b)
                if #a ~= #b then
                    return #a < #b
                end
                return a < b
            end)
            return keys
        end
        local enum_options = {}
        for k, v in pairs(options) do
            enum_options[k] = v
        end
        -- a side that enumerated completely at this length bound
        -- yields the same word set under any bigger form budget, so
        -- re-running it only burns the deadline: re-enumerate a side
        -- when the length grew (both) or its budget grew while it was
        -- incomplete
        local words1, complete1, words2, complete2
        local ran1_len, ran1_budget, ran2_len, ran2_budget
        while not deadline_expired(options) do
            enum_options.max_words = enum_words
            if not ran1_len or ran1_len ~= max_length
                    or (not complete1 and ran1_budget ~= enum_words) then
                words1, complete1 = automata
                    .grammar_enumerate_words_yieldfirst(
                        grammar1, max_length, enum_options)
                ran1_len, ran1_budget = max_length, enum_words
                collectgarbage("collect")
            end
            if not ran2_len or ran2_len ~= max_length
                    or (not complete2 and ran2_budget ~= enum_words) then
                words2, complete2 = automata
                    .grammar_enumerate_words_yieldfirst(
                        grammar2, max_length, enum_options)
                ran2_len, ran2_budget = max_length, enum_words
            end
            if not cex1 and not inc12 then
                for _, w in ipairs(sorted_keys(words1)) do
                    if deadline_expired(options) then
                        break
                    end
                    if not words2[w] then
                        if complete2 then
                            cex1 = w
                            break
                        end
                        local result, capped = automata
                            .grammar_contains_word(w, grammar2, options)
                        if result == false and not capped then
                            cex1 = w
                            break
                        end
                        -- "capped" means unverifiable within caps; true
                        -- means the enumeration of grammar2 was just
                        -- incomplete
                    end
                end
            end
            if not cex2 and not inc21 then
                for _, w in ipairs(sorted_keys(words2)) do
                    if deadline_expired(options) then
                        break
                    end
                    if not words1[w] then
                        if complete1 then
                            cex2 = w
                            break
                        end
                        local result, capped = automata
                            .grammar_contains_word(w, grammar1, options)
                        if result == false and not capped then
                            cex2 = w
                            break
                        end
                    end
                end
            end
            -- the reverse direction went unprobed when the forward
            -- map failed; if this side's scan also comes up empty an
            -- inclusion is plausible, so spend one bounded probe --
            -- a proven reverse inclusion upgrades a lone forward
            -- witness to a real strict superset and closes the loop
            if not cex2 and not inc21 and not inc21_tried
                    and not deadline_expired(options) then
                inc21_tried = true
                inc21 = csg_simulates(grammar2, grammar1, options)
                    or nil
            end
            -- deepen the search while a direction still lacks its
            -- witness: both enumerations complete means the missing
            -- witness provably does not exist at this length, so only
            -- a deeper length bound can find it; an incomplete side
            -- instead capped on explored forms, so a bigger form
            -- budget is what reaches further.  A proven inclusion
            -- closes its direction too: the counterexample provably
            -- cannot exist, so both directions being decided is the
            -- loop's exit -- not just two witnesses in hand
            if (cex1 or inc12) and (cex2 or inc21) then
                break
            end
            collectgarbage("collect")
            if grammar_memory_exceeded(options) then
                -- memory is exhausted: another round with a bigger
                -- form budget would just hit the same wall, and the
                -- witnesses not found may still exist -- honest nil
                break
            end
            if complete1 and complete2 then
                if max_length >= ceiling then
                    break
                end
                max_length = max_length + 2
            else
                if enum_words >= enum_words_ceiling then
                    break
                end
                enum_words = math.min(enum_words * 4,
                                      enum_words_ceiling)
            end
        end
        if cex1 and cex2 then
            return "!=", cex1, cex2
        elseif cex1 then
            return ">", cex1
        elseif cex2 then
            return "<", nil, cex2
        end
        return nil
    end

    -- per-grammar sentential-form caches accumulate up to the
    -- max_words bound per call and are keyed on the grammar text, so
    -- batch runs would otherwise grow without limit; the comparison
    -- does not need them afterwards
    function automata.grammar_compare_languages(grammar1, grammar2,
                                                options)
        -- a relative time budget translates into an absolute deadline
        -- once, so every bounded search below checks the same clock;
        -- an expired deadline behaves like any other cap: the
        -- comparison just reports "unknown"
        if options and options.max_seconds and not options.deadline then
            local with_deadline = {}
            for key, value in pairs(options) do
                with_deadline[key] = value
            end
            with_deadline.deadline = os.clock() + options.max_seconds
            options = with_deadline
        end
        -- strip provably dead context rules: a grammar that is only
        -- syntactically non-context-free then rejoins the whole
        -- context-free machinery, with the same language
        local stripped1 = strip_dead_noncf_rules(grammar1)
        local stripped2 = strip_dead_noncf_rules(grammar2)
        local rel, w1, w2 = grammar_compare_languages_impl(
            stripped1 or grammar1, stripped2 or grammar2, options)
        automata.clear_grammar_cache_entry(grammar1)
        automata.clear_grammar_cache_entry(grammar2)
        if stripped1 then
            automata.clear_grammar_cache_entry(stripped1)
        end
        if stripped2 then
            automata.clear_grammar_cache_entry(stripped2)
        end
        return rel, w1, w2
    end

    local function process_grammar_side(side)
        local possible_name_parts = {
            ["'"]=true,
            ["0"]=true,
            ["1"]=true,
            ["2"]=true,
            ["3"]=true,
            ["4"]=true,
            ["5"]=true,
            ["6"]=true,
            ["7"]=true,
            ["8"]=true,
            ["9"]=true,
            ["_"]=true,
        }
        local found_bad = false
        if type(side) == "string" then
            side = automata.tokenise_word(side)
        end
        local new_side = automata.make_token_sequence()
        -- a lowercase letter continues an underscore-letter
        -- subscript: "T_a" and "T_ab" are single variables, but
        -- "T_1a" is variable T_1 followed by terminal a
        local in_subscript = false
        for i=1,side:len() do
            local char = side:get_char(i)
            local merge = possible_name_parts[char] or
                (in_subscript and char:match("%l") ~= nil)
            if merge and i > 1 then
                found_bad = true
                local prev = new_side:get_char(new_side:len())
                new_side:remove_right_modify()
                prev = prev .. char
                new_side:insert_right_modify(prev)
                in_subscript = char == "_" or
                    (in_subscript and char:match("%l") ~= nil)
            else
                new_side:insert_right_modify(char)
                in_subscript = false
            end
        end
        return new_side, found_bad
    end

    -- grammar answers parse in two stages:
    --
    --   1. normalise_grammar_text: ordinary-Lua repairs (quotes,
    --      comma-prose lines, prime variants, arrow spellings) reduce
    --      the raw answer to a list of normalised "lhs→rhs|…" lines
    --   2. rule_grammar: a strict LPeg grammar parses each line into
    --      lhs + alternative list; the policy code in parse_rules then
    --      applies the grammar-state dependent fixes (capitalisation,
    --      prose heads, name merging, start variable)
    --
    -- every repair is recorded as {kind=…, line=…} so callers can
    -- report which tolerance kicked in instead of a bare found_bad

    local function normalise_grammar_text(rules)
        local lines = {}
        local repairs = {}
        local function repair(kind, line)
            repairs[#repairs + 1] = {kind = kind, line = line}
        end
        rules = trim(rules)
        -- answers occasionally come wrapped in quotes ('...' or "...")
        if rules:match("^[\'\"]") and rules:match("[\'\"]$") then
            rules = rules:gsub("^[\'\"]", ""):gsub("[\'\"]$", "")
            repair("quotes")
        end
        for lineno, raw_line in ipairs(split(rules, "\n")) do
            -- a line mixing rule fragments with prose is prose: "Here,
            -- S→ ABB, A→Aaa ..." -- every fragment of a real
            -- comma-separated rule list contains an arrow
            local pieces = split(raw_line, ",")
            local contaminated = false
            if #pieces > 1 then
                for _, piece in ipairs(pieces) do
                    local p = remove_whitespace(piece)
                        :gsub("->", "→"):gsub("=>", "→"):gsub("⇒", "→")
                    -- the same safe mistyped-arrow repair used below;
                    -- an empty fragment is just a stray comma
                    if p == "" then
                        -- ignore
                    elseif not p:find("→") and
                        not p:match("^[A-Z][A-Za-z0-9_']*%-") then
                        contaminated = true
                        break
                    end
                end
            end
            if contaminated then
                repair("prose_line", lineno)
                pieces = {}
            end
            for _, piece in ipairs(pieces) do
                local rule_line = remove_whitespace(piece)
                -- students write variable primes as ', `, ´, ’, ′
                -- or "; normalise them all to ' so names stay
                -- consistent
                local fixed = rule_line:gsub("`", "'"):gsub("´", "'")
                    :gsub("’", "'"):gsub("‘", "'"):gsub("′", "'")
                    :gsub("″", "'"):gsub('"', "'")
                if fixed ~= rule_line then
                    repair("prime_variant", lineno)
                    rule_line = fixed
                end
                rule_line = rule_line:gsub("->", "→")
                rule_line = rule_line:gsub("=>", "→")
                rule_line = rule_line:gsub("⇒", "→")
                if not rule_line:find("→") then
                    -- a lone "-" before a capitalised lhs is a mistyped
                    -- arrow ("S-AB"); only repair that position
                    local fixed = rule_line:gsub(
                        "^([A-Z][A-Za-z0-9_']*)-", "%1→", 1)
                    if fixed ~= rule_line then
                        repair("dash_arrow", lineno)
                        rule_line = fixed
                    end
                end
                lines[#lines + 1] = {text = rule_line, line = lineno}
            end
        end
        return lines, repairs
    end
    automata.normalise_grammar_text = normalise_grammar_text

    -- "lhs→rhs|rhs|…"; an rhs may be empty ("S→" / "S→a|"), any
    -- further "→…" tail is captured separately as truncation.  The
    -- side texts exclude the *sequences* "→" and "|" via pattern
    -- difference -- lpeg.S on the multibyte "→" would wrongly exclude
    -- its individual UTF-8 bytes (E2, 86, 92) wherever they occur
    -- inside other characters
    local side_char = 1 - (lpeg.P"→" + lpeg.P"|")
    local rule_grammar = lpeg.P{
        "rule",
        rule = lpeg.Ct(
            lpeg.Cg(lpeg.C((1 - lpeg.P"→")^1), "lhs")
          * lpeg.P"→"
          * lpeg.Cg(lpeg.Ct(
                lpeg.C(side_char^0)
              * (lpeg.P"|" * lpeg.C(side_char^0))^0), "rhss")
          * lpeg.Cg((lpeg.P"→" * lpeg.P(1)^0
                     * lpeg.Cc(true))^-1, "truncated")
          * -1)
    }

    function automata.parse_rules(rules, options)
        if type(options) == "nil" then
            options = {}
        end
        local grammar = automata.make_grammar()
        local lines, repairs = normalise_grammar_text(rules)
        local function repair(kind, line)
            repairs[#repairs + 1] = {kind = kind, line = line}
        end
        local first_single_var_lhs = nil
        for _, entry in ipairs(lines) do
            local parsed = lpeg.match(rule_grammar, entry.text)
            if not parsed then
                -- no arrow at all: not a rule, silently ignored; an
                -- arrow with an empty lhs is a broken rule
                if entry.text:find("→") then
                    repair("missing_side", entry.line)
                end
            else
                -- Cg of a non-matching optional captures "" (truthy!),
                -- so compare against the Cc(true) marker explicitly
                if parsed.truncated == true then
                    -- "A→B→C" keeps lhs + first rhs; flag the loss
                    repair("extra_arrow", entry.line)
                end
                local lhs, rhss = parsed.lhs, parsed.rhss
                if #rhss == 1 and rhss[1] == "" then
                    -- "S→": a side is missing
                    repair("missing_side", entry.line)
                else
                    if lhs == "s" and (options.correct_lhs_capitalisation
                            or not grammar:get_variables()["S"]) then
                        -- a lone lowercase "s" head is a mistyped "S";
                        -- unless "S" is already in use (then "s" is
                        -- presumably deliberate) we fix it even
                        -- without the capitalisation option, which
                        -- other lowercase heads still require
                        lhs = "S"
                    elseif options.correct_lhs_capitalisation
                            and lhs:match("^[a-z][0-9_']*$") then
                        -- a lowercase rule head is a mistyped
                        -- variable ("i->c" means I)
                        lhs = lhs:upper()
                        repair("lhs_capitalisation", entry.line)
                    end
                    -- an lhs that cannot be an identifier or a short
                    -- context-sensitive head is prose ("...either S")
                    -- or function notation ("U(AB)"): long lowercase
                    -- runs and non-name characters give those away
                    if lhs:match("%l%l%l") or lhs:match("[^%w_'#]")
                            then
                        repair("prose_lhs", entry.line)
                        lhs = nil
                    end
                    if lhs then
                        for _, rhs in ipairs(rhss) do
                            if rhs == "" and #rhss > 1 then
                                -- "S→a|" might mean "S→a|λ": we keep
                                -- the literal reading but flag the
                                -- ambiguity
                                repair("empty_alternative", entry.line)
                            end
                            if rhs ~= "" then
                                local low = rhs:gsub("^\\", ""):lower()
                                if rhs == "λ" or rhs == "ε" then
                                    rhs = ""
                                elseif low == "lambda"
                                    or low == "lamda"
                                    or low == "epsilon"
                                    or low == "eps" then
                                    -- spelled-out empty word, e.g.
                                    -- "\lamda"
                                    repair("empty_word_spelled",
                                           entry.line)
                                    rhs = ""
                                end
                            end
                            local bad
                            lhs, bad = process_grammar_side(lhs)
                            if bad then
                                repair("name_merge", entry.line)
                            end
                            rhs, bad = process_grammar_side(rhs)
                            if bad then
                                repair("name_merge", entry.line)
                            end
                            grammar:add_rule(lhs, rhs)
                            if not first_single_var_lhs
                                    and lhs:len() == 1
                                    and grammar:get_variables()
                                        [lhs:get_char(1)] then
                                first_single_var_lhs = lhs:get_char(1)
                            end
                        end
                    end
                end
            end
        end

        if options.start_variable_explicit then
            grammar:set_start_variable(options.start_variable_explicit)
        elseif grammar:get_variables()["S'"] then
            grammar:set_start_variable("S'")
            repair("start_variable_prime")
        elseif not grammar:get_variables()["S"]
                and first_single_var_lhs then
            -- there is no "S" anywhere: the start variable is simply
            -- named differently (e.g. renamed to T); a rule-less "S"
            -- would silently evaluate to the empty language
            grammar:set_start_variable(first_single_var_lhs)
            repair("start_variable_renamed")
        else
            grammar:add_symbol("S")
            grammar:set_start_variable("S")
        end
        return grammar, #repairs > 0, repairs
    end
end
